//! A simple arena-based DOM tree.

pub type NodeId = usize;

pub const NS_HTML: &str = "http://www.w3.org/1999/xhtml";
pub const NS_SVG: &str = "http://www.w3.org/2000/svg";
pub const NS_MATHML: &str = "http://www.w3.org/1998/Math/MathML";
pub const NS_XLINK: &str = "http://www.w3.org/1999/xlink";
pub const NS_XML: &str = "http://www.w3.org/XML/1998/namespace";
pub const NS_XMLNS: &str = "http://www.w3.org/2000/xmlns/";
pub const NS_NONE: &str = "";

#[derive(Clone, Debug)]
pub struct Attr {
    pub ns: &'static str,
    pub local: String,
    pub prefix: Option<&'static str>,
    pub value: String,
}

#[derive(Clone, Debug)]
pub struct ElementData {
    pub ns: &'static str,
    pub local: String,
    /// Sorted by (ns, local), unique.
    pub attrs: Vec<Attr>,
    pub template_contents: Option<NodeId>,
}

impl ElementData {
    pub fn get_attr(&self, local: &str) -> Option<&str> {
        self.attrs
            .iter()
            .find(|a| a.ns.is_empty() && a.local == local)
            .map(|a| a.value.as_str())
    }

    pub fn has_attr(&self, local: &str) -> bool {
        self.get_attr(local).is_some()
    }

    pub fn set_attr(&mut self, local: &str, value: String) {
        for a in self.attrs.iter_mut() {
            if a.ns.is_empty() && a.local == local {
                a.value = value;
                return;
            }
        }
        self.insert_attr_if_missing(Attr { ns: NS_NONE, local: local.to_string(), prefix: None, value });
    }

    /// Insert keeping the order; returns false if an attribute with the same
    /// expanded name already exists.
    pub fn insert_attr_if_missing(&mut self, attr: Attr) -> bool {
        match self
            .attrs
            .binary_search_by(|a| (a.ns, a.local.as_str()).cmp(&(attr.ns, attr.local.as_str())))
        {
            Ok(_) => false,
            Err(pos) => {
                self.attrs.insert(pos, attr);
                true
            }
        }
    }

    /// Insert, replacing an existing attribute (BTreeMap collect semantics).
    pub fn insert_attr_replace(&mut self, attr: Attr) {
        match self
            .attrs
            .binary_search_by(|a| (a.ns, a.local.as_str()).cmp(&(attr.ns, attr.local.as_str())))
        {
            Ok(pos) => self.attrs[pos] = attr,
            Err(pos) => self.attrs.insert(pos, attr),
        }
    }

    pub fn is_html(&self, name: &str) -> bool {
        self.ns == NS_HTML && self.local == name
    }
}

#[derive(Clone, Debug)]
pub enum NodeData {
    Document,
    DocumentFragment,
    Doctype { name: String, public_id: String, system_id: String },
    Text(String),
    Comment(String),
    Element(ElementData),
}

#[derive(Clone, Debug)]
pub struct Node {
    pub parent: Option<NodeId>,
    pub prev_sibling: Option<NodeId>,
    pub next_sibling: Option<NodeId>,
    pub first_child: Option<NodeId>,
    pub last_child: Option<NodeId>,
    pub data: NodeData,
}

pub struct Dom {
    pub nodes: Vec<Node>,
}

pub const DOCUMENT: NodeId = 0;

impl Dom {
    pub fn new() -> Dom {
        let mut d = Dom { nodes: Vec::new() };
        d.new_node(NodeData::Document);
        d
    }

    pub fn new_node(&mut self, data: NodeData) -> NodeId {
        self.nodes.push(Node {
            parent: None,
            prev_sibling: None,
            next_sibling: None,
            first_child: None,
            last_child: None,
            data,
        });
        self.nodes.len() - 1
    }

    #[inline]
    pub fn node(&self, id: NodeId) -> &Node {
        &self.nodes[id]
    }

    #[inline]
    pub fn parent(&self, id: NodeId) -> Option<NodeId> {
        self.nodes[id].parent
    }
    #[inline]
    pub fn first_child(&self, id: NodeId) -> Option<NodeId> {
        self.nodes[id].first_child
    }
    #[inline]
    pub fn last_child(&self, id: NodeId) -> Option<NodeId> {
        self.nodes[id].last_child
    }
    #[inline]
    pub fn next_sibling(&self, id: NodeId) -> Option<NodeId> {
        self.nodes[id].next_sibling
    }
    #[inline]
    pub fn prev_sibling(&self, id: NodeId) -> Option<NodeId> {
        self.nodes[id].prev_sibling
    }

    pub fn element(&self, id: NodeId) -> Option<&ElementData> {
        match &self.nodes[id].data {
            NodeData::Element(e) => Some(e),
            _ => None,
        }
    }

    pub fn element_mut(&mut self, id: NodeId) -> Option<&mut ElementData> {
        match &mut self.nodes[id].data {
            NodeData::Element(e) => Some(e),
            _ => None,
        }
    }

    pub fn is_element(&self, id: NodeId) -> bool {
        matches!(self.nodes[id].data, NodeData::Element(_))
    }

    pub fn text(&self, id: NodeId) -> Option<&str> {
        match &self.nodes[id].data {
            NodeData::Text(t) => Some(t.as_str()),
            _ => None,
        }
    }

    pub fn detach(&mut self, id: NodeId) {
        let parent = self.nodes[id].parent.take();
        let prev = self.nodes[id].prev_sibling.take();
        let next = self.nodes[id].next_sibling.take();
        match next {
            Some(n) => self.nodes[n].prev_sibling = prev,
            None => {
                if let Some(p) = parent {
                    self.nodes[p].last_child = prev;
                }
            }
        }
        match prev {
            Some(p) => self.nodes[p].next_sibling = next,
            None => {
                if let Some(par) = parent {
                    self.nodes[par].first_child = next;
                }
            }
        }
    }

    pub fn append(&mut self, parent: NodeId, child: NodeId) {
        self.detach(child);
        self.nodes[child].parent = Some(parent);
        match self.nodes[parent].last_child {
            Some(last) => {
                self.nodes[last].next_sibling = Some(child);
                self.nodes[child].prev_sibling = Some(last);
            }
            None => {
                self.nodes[parent].first_child = Some(child);
            }
        }
        self.nodes[parent].last_child = Some(child);
    }

    pub fn insert_before(&mut self, sibling: NodeId, child: NodeId) {
        self.detach(child);
        let parent = self.nodes[sibling].parent;
        let prev = self.nodes[sibling].prev_sibling;
        self.nodes[child].parent = parent;
        self.nodes[child].next_sibling = Some(sibling);
        self.nodes[child].prev_sibling = prev;
        self.nodes[sibling].prev_sibling = Some(child);
        match prev {
            Some(p) => self.nodes[p].next_sibling = Some(child),
            None => {
                if let Some(par) = parent {
                    self.nodes[par].first_child = Some(child);
                }
            }
        }
    }

    /// Append text to parent, merging with a trailing text node.
    pub fn append_text(&mut self, parent: NodeId, text: &str) {
        if let Some(last) = self.nodes[parent].last_child {
            if let NodeData::Text(t) = &mut self.nodes[last].data {
                t.push_str(text);
                return;
            }
        }
        let n = self.new_node(NodeData::Text(text.to_string()));
        self.append(parent, n);
    }

    /// Insert text before sibling, merging with the previous text node.
    pub fn insert_text_before(&mut self, sibling: NodeId, text: &str) {
        if let Some(prev) = self.nodes[sibling].prev_sibling {
            if let NodeData::Text(t) = &mut self.nodes[prev].data {
                t.push_str(text);
                return;
            }
        }
        let n = self.new_node(NodeData::Text(text.to_string()));
        self.insert_before(sibling, n);
    }

    pub fn children(&self, id: NodeId) -> Vec<NodeId> {
        let mut v = Vec::new();
        let mut c = self.nodes[id].first_child;
        while let Some(x) = c {
            v.push(x);
            c = self.nodes[x].next_sibling;
        }
        v
    }
}
EOF
echo ok"}

