//! HTML tokenizer following the WHATWG tokenization algorithm.

use crate::entities::ENTITIES;

#[derive(Debug, Clone)]
pub struct Tag {
    pub name: String,
    pub attrs: Vec<(String, String)>,
    pub self_closing: bool,
}

#[derive(Debug, Clone, Default)]
pub struct Doctype {
    pub name: Option<String>,
    pub public_id: Option<String>,
    pub system_id: Option<String>,
    pub force_quirks: bool,
}

#[derive(Debug, Clone)]
pub enum Token {
    Doctype(Doctype),
    StartTag(Tag),
    EndTag(Tag),
    Comment(String),
    Char(char),
    Eof,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Data,
    Rcdata,
    Rawtext,
    ScriptData,
    Plaintext,
    TagOpen,
    EndTagOpen,
    TagName,
    RcdataLt,
    RcdataEndTagOpen,
    RcdataEndTagName,
    RawtextLt,
    RawtextEndTagOpen,
    RawtextEndTagName,
    ScriptDataLt,
    ScriptDataEndTagOpen,
    ScriptDataEndTagName,
    ScriptDataEscapeStart,
    ScriptDataEscapeStartDash,
    ScriptDataEscaped,
    ScriptDataEscapedDash,
    ScriptDataEscapedDashDash,
    ScriptDataEscapedLt,
    ScriptDataEscapedEndTagOpen,
    ScriptDataEscapedEndTagName,
    ScriptDataDoubleEscapeStart,
    ScriptDataDoubleEscaped,
    ScriptDataDoubleEscapedDash,
    ScriptDataDoubleEscapedDashDash,
    ScriptDataDoubleEscapedLt,
    ScriptDataDoubleEscapeEnd,
    BeforeAttrName,
    AttrName,
    AfterAttrName,
    BeforeAttrValue,
    AttrValueDq,
    AttrValueSq,
    AttrValueUnq,
    AfterAttrValueQuoted,
    SelfClosingStartTag,
    BogusComment,
    MarkupDeclOpen,
    CommentStart,
    CommentStartDash,
    Comment,
    CommentEndDash,
    CommentEnd,
    CommentEndBang,
    Doctype,
    BeforeDoctypeName,
    DoctypeName,
    AfterDoctypeName,
    AfterDoctypePublicKw,
    BeforeDoctypePublicId,
    DoctypePublicIdDq,
    DoctypePublicIdSq,
    AfterDoctypePublicId,
    BetweenDoctypePublicSystem,
    AfterDoctypeSystemKw,
    BeforeDoctypeSystemId,
    DoctypeSystemIdDq,
    DoctypeSystemIdSq,
    AfterDoctypeSystemId,
    BogusDoctype,
    CdataSection,
    CdataSectionBracket,
    CdataSectionEnd,
}

pub trait TokenSink {
    /// Process a token; may return a new tokenizer state to switch to.
    fn process_token(&mut self, tok: Token) -> Option<State>;
    /// Whether the adjusted current node is present and not in the HTML namespace.
    fn adjusted_current_node_is_foreign(&self) -> bool;
}

#[derive(PartialEq, Eq, Clone, Copy)]
enum TagKind {
    Start,
    End,
}

pub struct Tokenizer<'a, S: TokenSink> {
    input: &'a [char],
    pos: usize,
    state: State,
    pub sink: S,
    // current tag
    tag_kind: TagKind,
    tag_name: String,
    tag_self_closing: bool,
    tag_attrs: Vec<(String, String)>,
    attr_name: String,
    attr_value: String,
    have_attr: bool,
    last_start_tag: String,
    temp_buf: String,
    comment: String,
    doctype: Doctype,
    eof_emitted: bool,
}

fn is_ws(c: char) -> bool {
    matches!(c, '\t' | '\n' | '\x0c' | ' ')
}

fn c1_replacement(n: u32) -> Option<char> {
    let table: [u32; 32] = [
        0x20AC, 0, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021, 0x02C6, 0x2030, 0x0160, 0x2039,
        0x0152, 0, 0x017D, 0, 0, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014, 0x02DC,
        0x2122, 0x0161, 0x203A, 0x0153, 0, 0x017E, 0x0178,
    ];
    let v = table[(n - 0x80) as usize];
    if v == 0 {
        None
    } else {
        char::from_u32(v)
    }
}

/// Preprocess the input: normalize newlines.
pub fn preprocess(s: &str) -> Vec<char> {
    let mut out = Vec::with_capacity(s.len());
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\r' {
            if chars.peek() == Some(&'\n') {
                chars.next();
            }
            out.push('\n');
        } else {
            out.push(c);
        }
    }
    out
}

impl<'a, S: TokenSink> Tokenizer<'a, S> {
    pub fn new(input: &'a [char], sink: S) -> Self {
        Tokenizer {
            input,
            pos: 0,
            state: State::Data,
            sink,
            tag_kind: TagKind::Start,
            tag_name: String::new(),
            tag_self_closing: false,
            tag_attrs: Vec::new(),
            attr_name: String::new(),
            attr_value: String::new(),
            have_attr: false,
            last_start_tag: String::new(),
            temp_buf: String::new(),
            comment: String::new(),
            doctype: Doctype::default(),
            eof_emitted: false,
        }
    }

    #[inline]
    fn consume(&mut self) -> Option<char> {
        if self.pos < self.input.len() {
            let c = self.input[self.pos];
            self.pos += 1;
            Some(c)
        } else {
            // Advance anyway so that reconsume works symmetrically.
            self.pos += 1;
            None
        }
    }

    #[inline]
    fn reconsume(&mut self) {
        self.pos -= 1;
    }

    #[inline]
    fn peek_at(&self, off: usize) -> Option<char> {
        self.input.get(self.pos + off).copied()
    }

    fn emit(&mut self, tok: Token) {
        let is_eof = matches!(tok, Token::Eof);
        if let Some(st) = self.sink.process_token(tok) {
            self.state = st;
        }
        if is_eof {
            self.eof_emitted = true;
        }
    }

    #[inline]
    fn emit_char(&mut self, c: char) {
        self.emit(Token::Char(c));
    }

    fn emit_str(&mut self, s: &str) {
        for c in s.chars() {
            self.emit_char(c);
        }
    }

    fn emit_eof(&mut self) {
        self.emit(Token::Eof);
    }

    fn create_tag(&mut self, kind: TagKind) {
        self.tag_kind = kind;
        self.tag_name.clear();
        self.tag_self_closing = false;
        self.tag_attrs.clear();
        self.have_attr = false;
    }

    fn start_attr(&mut self) {
        self.finish_attr();
        self.have_attr = true;
        self.attr_name.clear();
        self.attr_value.clear();
    }

    fn finish_attr(&mut self) {
        if !self.have_attr {
            return;
        }
        self.have_attr = false;
        let name = std::mem::take(&mut self.attr_name);
        let value = std::mem::take(&mut self.attr_value);
        if self.tag_attrs.iter().any(|(n, _)| *n == name) {
            return;
        }
        self.tag_attrs.push((name, value));
    }

    fn emit_tag(&mut self) {
        self.finish_attr();
        let tag = Tag {
            name: std::mem::take(&mut self.tag_name),
            attrs: std::mem::take(&mut self.tag_attrs),
            self_closing: self.tag_self_closing,
        };
        self.state = State::Data;
        match self.tag_kind {
            TagKind::Start => {
                self.last_start_tag = tag.name.clone();
                self.emit(Token::StartTag(tag));
            }
            TagKind::End => {
                self.emit(Token::EndTag(tag));
            }
        }
    }

    fn emit_comment(&mut self) {
        let c = std::mem::take(&mut self.comment);
        self.emit(Token::Comment(c));
    }

    fn emit_doctype(&mut self) {
        let d = std::mem::take(&mut self.doctype);
        self.emit(Token::Doctype(d));
    }

    fn appropriate_end_tag(&self) -> bool {
        self.tag_kind == TagKind::End && !self.last_start_tag.is_empty() && self.tag_name == self.last_start_tag
    }

    fn lookahead_ci(&self, s: &str) -> bool {
        // Checks if the input starting at the current pos matches s (ASCII case-insensitive).
        let mut i = self.pos;
        for c in s.chars() {
            match self.input.get(i) {
                Some(&x) if x.to_ascii_lowercase() == c.to_ascii_lowercase() => {}
                _ => return false,
            }
            i += 1;
        }
        true
    }

    fn lookahead_exact(&self, s: &str) -> bool {
        let mut i = self.pos;
        for c in s.chars() {
            match self.input.get(i) {
                Some(&x) if x == c => {}
                _ => return false,
            }
            i += 1;
        }
        true
    }

    /// Consume a character reference (the '&' has already been consumed).
    /// Returns None if this is not a character reference (nothing consumed).
    fn consume_char_ref(&mut self, additional: Option<char>, in_attr: bool) -> Option<String> {
        let c = self.peek_at(0);
        match c {
            None | Some('\t') | Some('\n') | Some('\x0c') | Some(' ') | Some('<') | Some('&') => return None,
            Some(x) if Some(x) == additional => return None,
            Some('#') => {
                let start = self.pos;
                self.pos += 1;
                let hex = matches!(self.peek_at(0), Some('x') | Some('X'));
                if hex {
                    self.pos += 1;
                }
                let mut val: u64 = 0;
                let mut too_big = false;
                let mut ndigits = 0;
                while let Some(d) = self.peek_at(0) {
                    let dv = if hex { d.to_digit(16) } else { d.to_digit(10) };
                    match dv {
                        Some(v) if d.is_ascii() => {
                            val = val * if hex { 16 } else { 10 } + v as u64;
                            if val > 0x10FFFF {
                                too_big = true;
                                val = 0x110000;
                            }
                            ndigits += 1;
                            self.pos += 1;
                        }
                        _ => break,
                    }
                }
                if ndigits == 0 {
                    self.pos = start;
                    return None;
                }
                if self.peek_at(0) == Some(';') {
                    self.pos += 1;
                }
                let n = val as u32;
                let ch = if too_big || n > 0x10FFFF {
                    '\u{FFFD}'
                } else if n == 0 || (0xD800..=0xDFFF).contains(&n) {
                    '\u{FFFD}'
                } else if (0x80..=0x9F).contains(&n) {
                    match c1_replacement(n) {
                        Some(c) => c,
                        None => char::from_u32(n).unwrap(),
                    }
                } else {
                    char::from_u32(n).unwrap_or('\u{FFFD}')
                };
                Some(ch.to_string())
            }
            Some(_) => {
                // Named character reference: find the longest match.
                let mut buf = String::new();
                let mut best: Option<(usize, &'static str, &'static str)> = None; // (len in chars, name, value)
                let mut i = 0;
                loop {
                    let ch = match self.peek_at(i) {
                        Some(c) => c,
                        None => break,
                    };
                    buf.push(ch);
                    i += 1;
                    // Find whether any entity starts with buf.
                    let idx = ENTITIES.partition_point(|(n, _)| *n < buf.as_str());
                    if idx >= ENTITIES.len() || !ENTITIES[idx].0.starts_with(buf.as_str()) {
                        break;
                    }
                    if ENTITIES[idx].0 == buf {
                        best = Some((i, ENTITIES[idx].0, ENTITIES[idx].1));
                    }
                }
                match best {
                    None => None,
                    Some((len, name, value)) => {
                        if in_attr && !name.ends_with(';') {
                            if let Some(nc) = self.peek_at(len) {
                                if nc == '=' || nc.is_ascii_alphanumeric() {
                                    return None;
                                }
                            }
                        }
                        self.pos += len;
                        Some(value.to_string())
                    }
                }
            }
        }
    }

    pub fn run(&mut self) {
        while !self.eof_emitted {
            self.step();
        }
    }

    fn step(&mut self) {
        use State::*;
        match self.state {
            Data => {
                // Fast path for runs of ordinary characters.
                let c = self.consume();
                match c {
                    Some('&') => match self.consume_char_ref(None, false) {
                        Some(s) => self.emit_str(&s),
                        None => self.emit_char('&'),
                    },
                    Some('<') => self.state = TagOpen,
                    Some(c) => self.emit_char(c),
                    None => self.emit_eof(),
                }
            }
            Rcdata => match self.consume() {
                Some('&') => match self.consume_char_ref(None, false) {
                    Some(s) => self.emit_str(&s),
                    None => self.emit_char('&'),
                },
                Some('<') => self.state = RcdataLt,
                Some('\0') => self.emit_char('\u{FFFD}'),
                Some(c) => self.emit_char(c),
                None => self.emit_eof(),
            },
            Rawtext => match self.consume() {
                Some('<') => self.state = RawtextLt,
                Some('\0') => self.emit_char('\u{FFFD}'),
                Some(c) => self.emit_char(c),
                None => self.emit_eof(),
            },
            ScriptData => match self.consume() {
                Some('<') => self.state = ScriptDataLt,
                Some('\0') => self.emit_char('\u{FFFD}'),
                Some(c) => self.emit_char(c),
                None => self.emit_eof(),
            },
            Plaintext => match self.consume() {
                Some('\0') => self.emit_char('\u{FFFD}'),
                Some(c) => self.emit_char(c),
                None => self.emit_eof(),
            },
            TagOpen => match self.consume() {
                Some('!') => self.state = MarkupDeclOpen,
                Some('/') => self.state = EndTagOpen,
                Some(c) if c.is_ascii_alphabetic() => {
                    self.create_tag(TagKind::Start);
                    self.reconsume();
                    self.state = TagName;
                }
                Some('?') => {
                    self.comment.clear();
                    self.reconsume();
                    self.state = BogusComment;
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume();
                    self.state = Data;
                }
            },
            EndTagOpen => match self.consume() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.create_tag(TagKind::End);
                    self.reconsume();
                    self.state = TagName;
                }
                Some('>') => self.state = Data,
                None => {
                    self.emit_char('<');
                    self.emit_char('/');
                    self.emit_eof();
                }
                Some(_) => {
                    self.comment.clear();
                    self.reconsume();
                    self.state = BogusComment;
                }
            },
            TagName => match self.consume() {
                Some(c) if is_ws(c) => self.state = BeforeAttrName,
                Some('/') => self.state = SelfClosingStartTag,
                Some('>') => self.emit_tag(),
                Some('\0') => self.tag_name.push('\u{FFFD}'),
                Some(c) => self.tag_name.push(c.to_ascii_lowercase()),
                None => self.emit_eof(),
            },
            RcdataLt => self.lt_state(Rcdata, RcdataEndTagOpen),
            RcdataEndTagOpen => self.end_tag_open_state(Rcdata, RcdataEndTagName),
            RcdataEndTagName => self.end_tag_name_state(Rcdata),
            RawtextLt => self.lt_state(Rawtext, RawtextEndTagOpen),
            RawtextEndTagOpen => self.end_tag_open_state(Rawtext, RawtextEndTagName),
            RawtextEndTagName => self.end_tag_name_state(Rawtext),
            ScriptDataLt => match self.consume() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = ScriptDataEndTagOpen;
                }
                Some('!') => {
                    self.state = ScriptDataEscapeStart;
                    self.emit_char('<');
                    self.emit_char('!');
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume();
                    self.state = ScriptData;
                }
            },
            ScriptDataEndTagOpen => self.end_tag_open_state(ScriptData, ScriptDataEndTagName),
            ScriptDataEndTagName => self.end_tag_name_state(ScriptData),
            ScriptDataEscapeStart => match self.consume() {
                Some('-') => {
                    self.state = ScriptDataEscapeStartDash;
                    self.emit_char('-');
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptData;
                }
            },
            ScriptDataEscapeStartDash => match self.consume() {
                Some('-') => {
                    self.state = ScriptDataEscapedDashDash;
                    self.emit_char('-');
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptData;
                }
            },
            ScriptDataEscaped => match self.consume() {
                Some('-') => {
                    self.state = ScriptDataEscapedDash;
                    self.emit_char('-');
                }
                Some('<') => self.state = ScriptDataEscapedLt,
                Some('\0') => self.emit_char('\u{FFFD}'),
                Some(c) => self.emit_char(c),
                None => self.emit_eof(),
            },
            ScriptDataEscapedDash => match self.consume() {
                Some('-') => {
                    self.state = ScriptDataEscapedDashDash;
                    self.emit_char('-');
                }
                Some('<') => self.state = ScriptDataEscapedLt,
                Some('\0') => {
                    self.state = ScriptDataEscaped;
                    self.emit_char('\u{FFFD}');
                }
                Some(c) => {
                    self.state = ScriptDataEscaped;
                    self.emit_char(c);
                }
                None => self.emit_eof(),
            },
            ScriptDataEscapedDashDash => match self.consume() {
                Some('-') => self.emit_char('-'),
                Some('<') => self.state = ScriptDataEscapedLt,
                Some('>') => {
                    self.state = ScriptData;
                    self.emit_char('>');
                }
                Some('\0') => {
                    self.state = ScriptDataEscaped;
                    self.emit_char('\u{FFFD}');
                }
                Some(c) => {
                    self.state = ScriptDataEscaped;
                    self.emit_char(c);
                }
                None => self.emit_eof(),
            },
            ScriptDataEscapedLt => match self.consume() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = ScriptDataEscapedEndTagOpen;
                }
                Some(c) if c.is_ascii_alphabetic() => {
                    self.temp_buf.clear();
                    self.emit_char('<');
                    self.reconsume();
                    self.state = ScriptDataDoubleEscapeStart;
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume();
                    self.state = ScriptDataEscaped;
                }
            },
            ScriptDataEscapedEndTagOpen => self.end_tag_open_state(ScriptDataEscaped, ScriptDataEscapedEndTagName),
            ScriptDataEscapedEndTagName => self.end_tag_name_state(ScriptDataEscaped),
            ScriptDataDoubleEscapeStart => match self.consume() {
                Some(c) if is_ws(c) || c == '/' || c == '>' => {
                    self.state = if self.temp_buf == "script" { ScriptDataDoubleEscaped } else { ScriptDataEscaped };
                    self.emit_char(c);
                }
                Some(c) if c.is_ascii_alphabetic() => {
                    self.temp_buf.push(c.to_ascii_lowercase());
                    self.emit_char(c);
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptDataEscaped;
                }
            },
            ScriptDataDoubleEscaped => match self.consume() {
                Some('-') => {
                    self.state = ScriptDataDoubleEscapedDash;
                    self.emit_char('-');
                }
                Some('<') => {
                    self.state = ScriptDataDoubleEscapedLt;
                    self.emit_char('<');
                }
                Some('\0') => self.emit_char('\u{FFFD}'),
                Some(c) => self.emit_char(c),
                None => self.emit_eof(),
            },
            ScriptDataDoubleEscapedDash => match self.consume() {
                Some('-') => {
                    self.state = ScriptDataDoubleEscapedDashDash;
                    self.emit_char('-');
                }
                Some('<') => {
                    self.state = ScriptDataDoubleEscapedLt;
                    self.emit_char('<');
                }
                Some('\0') => {
                    self.state = ScriptDataDoubleEscaped;
                    self.emit_char('\u{FFFD}');
                }
                Some(c) => {
                    self.state = ScriptDataDoubleEscaped;
                    self.emit_char(c);
                }
                None => self.emit_eof(),
            },
            ScriptDataDoubleEscapedDashDash => match self.consume() {
                Some('-') => self.emit_char('-'),
                Some('<') => {
                    self.state = ScriptDataDoubleEscapedLt;
                    self.emit_char('<');
                }
                Some('>') => {
                    self.state = ScriptData;
                    self.emit_char('>');
                }
                Some('\0') => {
                    self.state = ScriptDataDoubleEscaped;
                    self.emit_char('\u{FFFD}');
                }
                Some(c) => {
                    self.state = ScriptDataDoubleEscaped;
                    self.emit_char(c);
                }
                None => self.emit_eof(),
            },
            ScriptDataDoubleEscapedLt => match self.consume() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = ScriptDataDoubleEscapeEnd;
                    self.emit_char('/');
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptDataDoubleEscaped;
                }
            },
            ScriptDataDoubleEscapeEnd => match self.consume() {
                Some(c) if is_ws(c) || c == '/' || c == '>' => {
                    self.state = if self.temp_buf == "script" { ScriptDataEscaped } else { ScriptDataDoubleEscaped };
                    self.emit_char(c);
                }
                Some(c) if c.is_ascii_alphabetic() => {
                    self.temp_buf.push(c.to_ascii_lowercase());
                    self.emit_char(c);
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptDataDoubleEscaped;
                }
            },
            BeforeAttrName => match self.consume() {
                Some(c) if is_ws(c) => {}
                Some('/') | Some('>') | None => {
                    self.reconsume();
                    self.state = AfterAttrName;
                }
                Some('=') => {
                    self.start_attr();
                    self.attr_name.push('=');
                    self.state = AttrName;
                }
                Some(_) => {
                    self.start_attr();
                    self.reconsume();
                    self.state = AttrName;
                }
            },
            AttrName => match self.consume() {
                Some(c) if is_ws(c) || c == '/' || c == '>' => {
                    self.reconsume();
                    self.state = AfterAttrName;
                }
                None => {
                    self.reconsume();
                    self.state = AfterAttrName;
                }
                Some('=') => self.state = BeforeAttrValue,
                Some('\0') => self.attr_name.push('\u{FFFD}'),
                Some(c) => self.attr_name.push(c.to_ascii_lowercase()),
            },
            AfterAttrName => match self.consume() {
                Some(c) if is_ws(c) => {}
                Some('/') => self.state = SelfClosingStartTag,
                Some('=') => self.state = BeforeAttrValue,
                Some('>') => self.emit_tag(),
                None => self.emit_eof(),
                Some(_) => {
                    self.start_attr();
                    self.reconsume();
                    self.state = AttrName;
                }
            },
            BeforeAttrValue => match self.consume() {
                Some(c) if is_ws(c) => {}
                Some('"') => self.state = AttrValueDq,
                Some('\'') => self.state = AttrValueSq,
                Some('>') => self.emit_tag(),
                _ => {
                    self.reconsume();
                    self.state = AttrValueUnq;
                }
            },
            AttrValueDq => match self.consume() {
                Some('"') => self.state = AfterAttrValueQuoted,
                Some('&') => match self.consume_char_ref(Some('"'), true) {
                    Some(s) => self.attr_value.push_str(&s),
                    None => self.attr_value.push('&'),
                },
                Some('\0') => self.attr_value.push('\u{FFFD}'),
                Some(c) => self.attr_value.push(c),
                None => self.emit_eof(),
            },
            AttrValueSq => match self.consume() {
                Some('\'') => self.state = AfterAttrValueQuoted,
                Some('&') => match self.consume_char_ref(Some('\''), true) {
                    Some(s) => self.attr_value.push_str(&s),
                    None => self.attr_value.push('&'),
                },
                Some('\0') => self.attr_value.push('\u{FFFD}'),
                Some(c) => self.attr_value.push(c),
                None => self.emit_eof(),
            },
            AttrValueUnq => match self.consume() {
                Some(c) if is_ws(c) => self.state = BeforeAttrName,
                Some('&') => match self.consume_char_ref(Some('>'), true) {
                    Some(s) => self.attr_value.push_str(&s),
                    None => self.attr_value.push('&'),
                },
                Some('>') => self.emit_tag(),
                Some('\0') => self.attr_value.push('\u{FFFD}'),
                Some(c) => self.attr_value.push(c),
                None => self.emit_eof(),
            },
            AfterAttrValueQuoted => match self.consume() {
                Some(c) if is_ws(c) => self.state = BeforeAttrName,
                Some('/') => self.state = SelfClosingStartTag,
                Some('>') => self.emit_tag(),
                None => self.emit_eof(),
                Some(_) => {
                    self.reconsume();
                    self.state = BeforeAttrName;
                }
            },
            SelfClosingStartTag => match self.consume() {
                Some('>') => {
                    self.tag_self_closing = true;
                    self.emit_tag();
                }
                None => self.emit_eof(),
                Some(_) => {
                    self.reconsume();
                    self.state = BeforeAttrName;
                }
            },
            BogusComment => match self.consume() {
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                None => {
                    self.emit_comment();
                    self.emit_eof();
                }
                Some('\0') => self.comment.push('\u{FFFD}'),
                Some(c) => self.comment.push(c),
            },
            MarkupDeclOpen => {
                if self.lookahead_exact("--") {
                    self.pos += 2;
                    self.comment.clear();
                    self.state = CommentStart;
                } else if self.lookahead_ci("doctype") {
                    self.pos += 7;
                    self.state = Doctype;
                } else if self.lookahead_exact("[CDATA[") && self.sink.adjusted_current_node_is_foreign() {
                    self.pos += 7;
                    self.state = CdataSection;
                } else {
                    self.comment.clear();
                    self.state = BogusComment;
                }
            }
            CommentStart => match self.consume() {
                Some('-') => self.state = CommentStartDash,
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                _ => {
                    self.reconsume();
                    self.state = Comment;
                }
            },
            CommentStartDash => match self.consume() {
                Some('-') => self.state = CommentEnd,
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                None => {
                    self.emit_comment();
                    self.emit_eof();
                }
                Some(_) => {
                    self.comment.push('-');
                    self.reconsume();
                    self.state = Comment;
                }
            },
            Comment => match self.consume() {
                Some('-') => self.state = CommentEndDash,
                Some('\0') => self.comment.push('\u{FFFD}'),
                Some(c) => self.comment.push(c),
                None => {
                    self.emit_comment();
                    self.emit_eof();
                }
            },
            CommentEndDash => match self.consume() {
                Some('-') => self.state = CommentEnd,
                None => {
                    self.emit_comment();
                    self.emit_eof();
                }
                Some(_) => {
                    self.comment.push('-');
                    self.reconsume();
                    self.state = Comment;
                }
            },
            CommentEnd => match self.consume() {
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                Some('!') => self.state = CommentEndBang,
                Some('-') => self.comment.push('-'),
                None => {
                    self.emit_comment();
                    self.emit_eof();
                }
                Some(_) => {
                    self.comment.push_str("--");
                    self.reconsume();
                    self.state = Comment;
                }
            },
            CommentEndBang => match self.consume() {
                Some('-') => {
                    self.comment.push_str("--!");
                    self.state = CommentEndDash;
                }
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                None => {
                    self.emit_comment();
                    self.emit_eof();
                }
                Some(_) => {
                    self.comment.push_str("--!");
                    self.reconsume();
                    self.state = Comment;
                }
            },
            Doctype => match self.consume() {
                Some(c) if is_ws(c) => self.state = BeforeDoctypeName,
                None => {
                    self.doctype = crate::tokenizer::Doctype::default();
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                Some(_) => {
                    self.reconsume();
                    self.state = BeforeDoctypeName;
                }
            },
            BeforeDoctypeName => match self.consume() {
                Some(c) if is_ws(c) => {}
                Some('>') => {
                    self.doctype = crate::tokenizer::Doctype::default();
                    self.doctype.force_quirks = true;
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype = crate::tokenizer::Doctype::default();
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                Some(c) => {
                    self.doctype = crate::tokenizer::Doctype::default();
                    let c = if c == '\0' { '\u{FFFD}' } else { c.to_ascii_lowercase() };
                    self.doctype.name = Some(c.to_string());
                    self.state = DoctypeName;
                }
            },
            DoctypeName => match self.consume() {
                Some(c) if is_ws(c) => self.state = AfterDoctypeName,
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                Some(c) => {
                    let c = if c == '\0' { '\u{FFFD}' } else { c.to_ascii_lowercase() };
                    self.doctype.name.get_or_insert_with(String::new).push(c);
                }
            },
            AfterDoctypeName => match self.consume() {
                Some(c) if is_ws(c) => {}
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                Some(_) => {
                    self.reconsume();
                    if self.lookahead_ci("public") {
                        self.pos += 6;
                        self.state = AfterDoctypePublicKw;
                    } else if self.lookahead_ci("system") {
                        self.pos += 6;
                        self.state = AfterDoctypeSystemKw;
                    } else {
                        self.pos += 1;
                        self.doctype.force_quirks = true;
                        self.state = BogusDoctype;
                    }
                }
            },
            AfterDoctypePublicKw => match self.consume() {
                Some(c) if is_ws(c) => self.state = BeforeDoctypePublicId,
                Some('"') => {
                    self.doctype.public_id = Some(String::new());
                    self.state = DoctypePublicIdDq;
                }
                Some('\'') => {
                    self.doctype.public_id = Some(String::new());
                    self.state = DoctypePublicIdSq;
                }
                Some('>') => {
                    self.doctype.force_quirks = true;
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                Some(_) => {
                    self.doctype.force_quirks = true;
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            BeforeDoctypePublicId => match self.consume() {
                Some(c) if is_ws(c) => {}
                Some('"') => {
                    self.doctype.public_id = Some(String::new());
                    self.state = DoctypePublicIdDq;
                }
                Some('\'') => {
                    self.doctype.public_id = Some(String::new());
                    self.state = DoctypePublicIdSq;
                }
                Some('>') => {
                    self.doctype.force_quirks = true;
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                Some(_) => {
                    self.doctype.force_quirks = true;
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            DoctypePublicIdDq | DoctypePublicIdSq => {
                let q = if self.state == DoctypePublicIdDq { '"' } else { '\'' };
                match self.consume() {
                    Some(c) if c == q => self.state = AfterDoctypePublicId,
                    Some('\0') => self.doctype.public_id.get_or_insert_with(String::new).push('\u{FFFD}'),
                    Some('>') => {
                        self.doctype.force_quirks = true;
                        self.state = Data;
                        self.emit_doctype();
                    }
                    None => {
                        self.doctype.force_quirks = true;
                        self.emit_doctype();
                        self.emit_eof();
                    }
                    Some(c) => self.doctype.public_id.get_or_insert_with(String::new).push(c),
                }
            }
            AfterDoctypePublicId => match self.consume() {
                Some(c) if is_ws(c) => self.state = BetweenDoctypePublicSystem,
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                Some('"') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdDq;
                }
                Some('\'') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdSq;
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                Some(_) => {
                    self.doctype.force_quirks = true;
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            BetweenDoctypePublicSystem => match self.consume() {
                Some(c) if is_ws(c) => {}
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                Some('"') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdDq;
                }
                Some('\'') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdSq;
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                Some(_) => {
                    self.doctype.force_quirks = true;
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            AfterDoctypeSystemKw => match self.consume() {
                Some(c) if is_ws(c) => self.state = BeforeDoctypeSystemId,
                Some('"') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdDq;
                }
                Some('\'') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdSq;
                }
                Some('>') => {
                    self.doctype.force_quirks = true;
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                Some(_) => {
                    self.doctype.force_quirks = true;
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            BeforeDoctypeSystemId => match self.consume() {
                Some(c) if is_ws(c) => {}
                Some('"') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdDq;
                }
                Some('\'') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdSq;
                }
                Some('>') => {
                    self.doctype.force_quirks = true;
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                Some(_) => {
                    self.doctype.force_quirks = true;
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            DoctypeSystemIdDq | DoctypeSystemIdSq => {
                let q = if self.state == DoctypeSystemIdDq { '"' } else { '\'' };
                match self.consume() {
                    Some(c) if c == q => self.state = AfterDoctypeSystemId,
                    Some('\0') => self.doctype.system_id.get_or_insert_with(String::new).push('\u{FFFD}'),
                    Some('>') => {
                        self.doctype.force_quirks = true;
                        self.state = Data;
                        self.emit_doctype();
                    }
                    None => {
                        self.doctype.force_quirks = true;
                        self.emit_doctype();
                        self.emit_eof();
                    }
                    Some(c) => self.doctype.system_id.get_or_insert_with(String::new).push(c),
                }
            }
            AfterDoctypeSystemId => match self.consume() {
                Some(c) if is_ws(c) => {}
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                Some(_) => {
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            BogusDoctype => match self.consume() {
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.emit_doctype();
                    self.emit_eof();
                }
                Some(_) => {}
            },
            CdataSection => match self.consume() {
                Some(']') => self.state = CdataSectionBracket,
                Some(c) => self.emit_char(c),
                None => self.emit_eof(),
            },
            CdataSectionBracket => match self.consume() {
                Some(']') => self.state = CdataSectionEnd,
                _ => {
                    self.emit_char(']');
                    self.reconsume();
                    self.state = CdataSection;
                }
            },
            CdataSectionEnd => match self.consume() {
                Some(']') => self.emit_char(']'),
                Some('>') => self.state = Data,
                _ => {
                    self.emit_char(']');
                    self.emit_char(']');
                    self.reconsume();
                    self.state = CdataSection;
                }
            },
        }
    }

    fn lt_state(&mut self, base: State, end_tag_open: State) {
        match self.consume() {
            Some('/') => {
                self.temp_buf.clear();
                self.state = end_tag_open;
            }
            _ => {
                self.emit_char('<');
                self.reconsume();
                self.state = base;
            }
        }
    }

    fn end_tag_open_state(&mut self, base: State, end_tag_name: State) {
        match self.consume() {
            Some(c) if c.is_ascii_alphabetic() => {
                self.create_tag(TagKind::End);
                self.reconsume();
                self.state = end_tag_name;
            }
            _ => {
                self.emit_char('<');
                self.emit_char('/');
                self.reconsume();
                self.state = base;
            }
        }
    }

    fn end_tag_name_state(&mut self, base: State) {
        let c = self.consume();
        match c {
            Some(ch) if is_ws(ch) && self.appropriate_end_tag() => {
                self.state = State::BeforeAttrName;
                return;
            }
            Some('/') if self.appropriate_end_tag() => {
                self.state = State::SelfClosingStartTag;
                return;
            }
            Some('>') if self.appropriate_end_tag() => {
                self.emit_tag();
                return;
            }
            Some(ch) if ch.is_ascii_alphabetic() => {
                self.tag_name.push(ch.to_ascii_lowercase());
                self.temp_buf.push(ch);
                return;
            }
            _ => {}
        }
        self.emit_char('<');
        self.emit_char('/');
        let buf = std::mem::take(&mut self.temp_buf);
        self.emit_str(&buf);
        self.reconsume();
        self.state = base;
    }
}
