    }

    fn lt_state(&mut self, base: State, end_tag_open: State) {
        match self.consume() {
            Some('/') => {
                self.temp_buf.clear();
                self.state = end_tag_open;
            }
            _ => {
                self.emit_char('<');
                self.reconsume();
                self.state = base;
            }
        }
    }

    fn end_tag_open_state(&mut self, base: State, end_tag_name: State) {
        match self.consume() {
            Some(c) if c.is_ascii_alphabetic() => {
                self.create_tag(TagKind::End);
                self.reconsume();
                self.state = end_tag_name;
            }
            _ => {
                self.emit_char('<');
                self.emit_char('/');
                self.reconsume();
                self.state = base;
            }
        }
    }

    fn end_tag_name_state(&mut self, base: State) {
        let c = self.consume();
        match c {
            Some(ch) if is_ws(ch) && self.appropriate_end_tag() => {
                self.state = State::BeforeAttrName;
                return;
            }
            Some('/') if self.appropriate_end_tag() => {
                self.state = State::SelfClosingStartTag;
                return;
            }
            Some('>') if self.appropriate_end_tag() => {
                self.emit_tag();
                return;
            }
            Some(ch) if ch.is_ascii_alphabetic() => {
                self.tag_name.push(ch.to_ascii_lowercase());
                self.temp_buf.push(ch);
                return;
            }
            _ => {}
        }
        self.emit_char('<');
        self.emit_char('/');
        let buf = std::mem::take(&mut self.temp_buf);
        self.emit_str(&buf);
        self.reconsume();
        self.state = base;
    }
}
