impl TokenSink for TreeBuilder {
    fn process_token(&mut self, tok: Token) -> Option<State> {
        self.next_state = None;
        if self.ignore_lf {
            self.ignore_lf = false;
            if let Token::Char('\n') = tok {
                return None;
            }
        }
        let mut tok = tok;
        loop {
            let step = if self.is_foreign(&tok) { self.foreign_content(tok) } else { self.step(self.mode, tok) };
            match step {
                Done => break,
                Reprocess(t) => tok = t,
            }
        }
        self.next_state.take()
    }

    fn adjusted_current_node_is_foreign(&self) -> bool {
        match self.open.last() {
            Some(&n) => self.dom.element(n).map(|e| e.ns != NS_HTML).unwrap_or(false),
            None => false,
        }
    }
}

pub fn parse_document(input: &str) -> Dom {
    let mut s = input;
    if let Some(rest) = s.strip_prefix('\u{FEFF}') {
        s = rest;
    }
    let chars = tokenizer::preprocess(s);
    let tb = TreeBuilder::new();
    let mut tok = tokenizer::Tokenizer::new(&chars, tb);
    tok.run();
    tok.sink.dom
}

impl TreeBuilder {
    pub fn new() -> TreeBuilder {
        TreeBuilder {
            dom: Dom::new(),
            mode: Mode::Initial,
            orig_mode: Mode::Initial,
            template_modes: Vec::new(),
            open: Vec::new(),
            afe: Vec::new(),
            head: None,
            form: None,
            frameset_ok: true,
            foster_parenting: false,
            pending_chars: Vec::new(),
            quirks: Quirks::NoQuirks,
            scripting: true,
            ignore_lf: false,
            next_state: None,
        }
    }

    // ---------- node helpers ----------

    fn elem(&self, id: NodeId) -> &ElementData {
        self.dom.element(id).expect("not an element")
    }

    fn is_html_named(&self, id: NodeId, name: &str) -> bool {
        match self.dom.element(id) {
            Some(e) => e.ns == NS_HTML && e.local == name,
            None => false,
        }
    }

    fn is_html_in(&self, id: NodeId, names: &[&str]) -> bool {
        match self.dom.element(id) {
            Some(e) => e.ns == NS_HTML && names.contains(&e.local.as_str()),
            None => false,
        }
    }

    fn is_special(&self, id: NodeId) -> bool {
        let e = self.elem(id);
        if e.ns == NS_HTML {
            SPECIAL_HTML.contains(&e.local.as_str())
        } else if e.ns == NS_MATHML {
            matches!(e.local.as_str(), "mi" | "mo" | "mn" | "ms" | "mtext" | "annotation-xml")
        } else if e.ns == NS_SVG {
            matches!(e.local.as_str(), "foreignObject" | "desc" | "title")
        } else {
            false
        }
    }

    fn is_mathml_text_integration_point(&self, id: NodeId) -> bool {
        let e = self.elem(id);
        e.ns == NS_MATHML && matches!(e.local.as_str(), "mi" | "mo" | "mn" | "ms" | "mtext")
    }

    fn is_html_integration_point(&self, id: NodeId) -> bool {
        let e = self.elem(id);
        e.ns == NS_SVG && matches!(e.local.as_str(), "foreignObject" | "desc" | "title")
    }

    fn current(&self) -> NodeId {
        *self.open.last().expect("no current node")
    }

    fn current_is(&self, name: &str) -> bool {
        match self.open.last() {
            Some(&n) => self.is_html_named(n, name),
            None => false,
        }
    }

    fn current_in(&self, names: &[&str]) -> bool {
        match self.open.last() {
            Some(&n) => self.is_html_in(n, names),
            None => false,
        }
    }

    fn is_scope_boundary(&self, id: NodeId, scope: Scope) -> bool {
        let e = self.elem(id);
        match scope {
            Scope::Select => !(e.ns == NS_HTML && (e.local == "optgroup" || e.local == "option")),
            Scope::Table => e.ns == NS_HTML && matches!(e.local.as_str(), "html" | "table" | "template"),
            _ => {
                let base = if e.ns == NS_HTML {
                    matches!(
                        e.local.as_str(),
                        "applet" | "caption" | "html" | "table" | "td" | "th" | "marquee" | "object" | "template"
                    )
                } else if e.ns == NS_MATHML {
                    matches!(e.local.as_str(), "mi" | "mo" | "mn" | "ms" | "mtext" | "annotation-xml")
                } else if e.ns == NS_SVG {
                    matches!(e.local.as_str(), "foreignObject" | "desc" | "title")
                } else {
                    false
                };
                if base {
                    return true;
                }
                match scope {
                    Scope::ListItem => e.ns == NS_HTML && (e.local == "ol" || e.local == "ul"),
                    Scope::Button => e.ns == NS_HTML && e.local == "button",
                    _ => false,
                }
            }
        }
    }

    fn in_scope_pred<F: Fn(&Self, NodeId) -> bool>(&self, scope: Scope, pred: F) -> bool {
        for &n in self.open.iter().rev() {
            if pred(self, n) {
                return true;
            }
            if self.is_scope_boundary(n, scope) {
                return false;
            }
        }
        false
    }

    fn in_scope(&self, name: &str, scope: Scope) -> bool {
        self.in_scope_pred(scope, |s, n| s.is_html_named(n, name))
    }

    fn in_scope_any(&self, names: &[&str], scope: Scope) -> bool {
        self.in_scope_pred(scope, |s, n| s.is_html_in(n, names))
    }

    fn in_scope_node(&self, node: NodeId, scope: Scope) -> bool {
        self.in_scope_pred(scope, |_, n| n == node)
    }

    fn stack_has(&self, name: &str) -> bool {
        self.open.iter().any(|&n| self.is_html_named(n, name))
    }

    fn pop(&mut self) -> NodeId {
        self.open.pop().expect("pop on empty stack")
    }

    fn pop_until(&mut self, name: &str) {
        while let Some(n) = self.open.pop() {
            if self.is_html_named(n, name) {
                break;
            }
        }
    }

    fn pop_until_any(&mut self, names: &[&str]) {
        while let Some(n) = self.open.pop() {
            if self.is_html_in(n, names) {
                break;
            }
        }
    }

    fn remove_from_stack(&mut self, node: NodeId) {
        if let Some(pos) = self.open.iter().rposition(|&n| n == node) {
            self.open.remove(pos);
        }
    }

    fn generate_implied_end(&mut self, except: Option<&str>) {
        loop {
            let cur = match self.open.last() {
                Some(&c) => c,
                None => return,
            };
            let e = self.elem(cur);
            if e.ns != NS_HTML || !IMPLIED_END.contains(&e.local.as_str()) {
                return;
            }
            if let Some(x) = except {
                if e.local == x {
                    return;
                }
            }
            self.open.pop();
        }
    }

    fn generate_implied_end_thorough(&mut self) {
        loop {
            let cur = match self.open.last() {
                Some(&c) => c,
                None => return,
            };
            if !self.is_html_in(cur, IMPLIED_END_THOROUGH) {
                return;
            }
            self.open.pop();
        }
    }

    fn close_p_element(&mut self) {
        self.generate_implied_end(Some("p"));
        self.pop_until("p");
    }

    fn close_p_if_in_button_scope(&mut self) {
        if self.in_scope("p", Scope::Button) {
            self.close_p_element();
        }
    }

    // ---------- element creation and insertion ----------

    fn create_element(&mut self, ns: &'static str, local: &str, attrs: Vec<Attr>) -> NodeId {
        let template_contents = if ns == NS_HTML && local == "template" {
            Some(self.dom.new_node(NodeData::DocumentFragment))
        } else {
            None
        };
        let mut ed = ElementData { ns, local: local.to_string(), attrs: Vec::new(), template_contents };
        for a in attrs {
            ed.insert_attr_replace(a);
        }
        self.dom.new_node(NodeData::Element(ed))
    }

    fn html_attrs(tag: &Tag) -> Vec<Attr> {
        tag.attrs
            .iter()
            .map(|(n, v)| Attr { ns: NS_NONE, local: n.clone(), prefix: None, value: v.clone() })
            .collect()
    }

    fn create_html_element_for(&mut self, tag: &Tag) -> NodeId {
        let attrs = Self::html_attrs(tag);
        self.create_element(NS_HTML, &tag.name, attrs)
    }

    /// Returns (parent, before) insertion location.
    fn appropriate_place(&self, override_target: Option<NodeId>) -> InsertionPoint {
        let target = override_target.unwrap_or_else(|| self.current());
        if !(self.foster_parenting && self.is_html_in(target, &["table", "tbody", "tfoot", "thead", "tr"])) {
            if self.is_html_named(target, "template") {
                return InsertionPoint::LastChild(self.elem(target).template_contents.unwrap());
            }
            return InsertionPoint::LastChild(target);
        }
        let mut i = self.open.len();
        while i > 0 {
            i -= 1;
            let elem = self.open[i];
            if self.is_html_named(elem, "template") {
                return InsertionPoint::LastChild(self.elem(elem).template_contents.unwrap());
            } else if self.is_html_named(elem, "table") {
                let prev = self.open[i - 1];
                return InsertionPoint::Foster { table: elem, prev };
            }
        }
        InsertionPoint::LastChild(self.open[0])
    }

    fn insert_node_at(&mut self, place: InsertionPoint, node: NodeId) {
        match place {
            InsertionPoint::LastChild(p) => self.dom.append(p, node),
            InsertionPoint::Foster { table, prev } => {
                if self.dom.parent(table).is_some() {
                    self.dom.insert_before(table, node);
                } else {
                    self.dom.append(prev, node);
                }
            }
        }
    }

    fn insert_text_at(&mut self, place: InsertionPoint, text: &str) {
        match place {
            InsertionPoint::LastChild(p) => self.dom.append_text(p, text),
            InsertionPoint::Foster { table, prev } => {
                if self.dom.parent(table).is_some() {
                    self.dom.insert_text_before(table, text);
                } else {
                    self.dom.append_text(prev, text);
                }
            }
        }
    }

    fn insert_element_node(&mut self, node: NodeId) {
        let place = self.appropriate_place(None);
        self.insert_node_at(place, node);
        self.open.push(node);
    }

    fn insert_html_element(&mut self, tag: &Tag) -> NodeId {
        let node = self.create_html_element_for(tag);
        self.insert_element_node(node);
        node
    }

    fn insert_foreign_element(&mut self, tag: &Tag, ns: &'static str) -> NodeId {
        let attrs = self.foreign_attrs(tag, ns);
        let node = self.create_element(ns, &tag.name, attrs);
        self.insert_element_node(node);
        node
    }

    fn foreign_attrs(&self, tag: &Tag, ns: &'static str) -> Vec<Attr> {
        let mut out = Vec::new();
        for (n, v) in &tag.attrs {
            let mut name = n.clone();
            if ns == NS_MATHML && name == "definitionurl" {
                name = "definitionURL".to_string();
            }
            if ns == NS_SVG {
                if let Some(&(_, adj)) = SVG_ATTR_ADJUST.iter().find(|(a, _)| *a == name) {
                    name = adj.to_string();
                }
            }
            let (ans, local, prefix): (&'static str, String, Option<&'static str>) = match name.as_str() {
                "xlink:actuate" | "xlink:arcrole" | "xlink:href" | "xlink:role" | "xlink:show" | "xlink:title"
                | "xlink:type" => (NS_XLINK, name[6..].to_string(), Some("xlink")),
                "xml:base" | "xml:lang" | "xml:space" => (NS_XML, name[4..].to_string(), Some("xml")),
                "xmlns" => (NS_XMLNS, "xmlns".to_string(), None),
                "xmlns:xlink" => (NS_XMLNS, "xlink".to_string(), Some("xmlns")),
                _ => (NS_NONE, name, None),
            };
            out.push(Attr { ns: ans, local, prefix, value: v.clone() });
        }
        out
    }

    fn insert_char(&mut self, c: char) {
        let place = self.appropriate_place(None);
        if let InsertionPoint::LastChild(p) = place {
            if p == DOCUMENT {
                return;
            }
        }
        let mut buf = [0u8; 4];
        self.insert_text_at(place, c.encode_utf8(&mut buf));
    }

    fn insert_comment(&mut self, text: String) {
        let place = self.appropriate_place(None);
        let n = self.dom.new_node(NodeData::Comment(text));
        self.insert_node_at(place, n);
    }

    fn append_comment_to(&mut self, parent: NodeId, text: String) {
        let n = self.dom.new_node(NodeData::Comment(text));
        self.dom.append(parent, n);
    }

    // ---------- active formatting elements ----------

    fn afe_position(&self, node: NodeId) -> Option<usize> {
        self.afe.iter().position(|e| matches!(e, Afe::Elem(n, _) if *n == node))
    }

    fn push_formatting(&mut self, tag: &Tag) -> NodeId {
        // Noah's Ark clause
        let mut first_match = None;
        let mut matches = 0;
        for i in (0..self.afe.len()).rev() {
            match &self.afe[i] {
                Afe::Marker => break,
                Afe::Elem(_, t) => {
                    if tags_equiv(t, tag) {
                        first_match = Some(i);
                        matches += 1;
                    }
                }
            }
        }
        if matches >= 3 {
            self.afe.remove(first_match.unwrap());
        }
        let node = self.insert_html_element(tag);
        self.afe.push(Afe::Elem(node, tag.clone()));
        node
    }

    fn reconstruct_formatting(&mut self) {
        if self.afe.is_empty() {
            return;
        }
        let last = self.afe.len() - 1;
        match &self.afe[last] {
            Afe::Marker => return,
            Afe::Elem(n, _) => {
                if self.open.contains(n) {
                    return;
                }
            }
        }
        let mut i = last;
        loop {
            if i == 0 {
                break;
            }
            i -= 1;
            let stop = match &self.afe[i] {
                Afe::Marker => true,
                Afe::Elem(n, _) => self.open.contains(n),
            };
            if stop {
                i += 1;
                break;
            }
        }
        while i <= last {
            let t = match &self.afe[i] {
                Afe::Elem(_, t) => t.clone(),
                Afe::Marker => unreachable!(),
            };
            let node = self.insert_html_element(&t);
            self.afe[i] = Afe::Elem(node, t);
            i += 1;
        }
    }

    fn clear_afe_to_marker(&mut self) {
        while let Some(e) = self.afe.pop() {
            if let Afe::Marker = e {
                break;
            }
        }
    }

    fn adoption_agency(&mut self, subject: &str) {
        // 1.
        if self.current_is(subject) {
            let cur = self.current();
            if self.afe_position(cur).is_none() {
                self.pop();
                return;
            }
        }
        for _ in 0..8 {
            // 5.
            let mut found = None;
            for i in (0..self.afe.len()).rev() {
                match &self.afe[i] {
                    Afe::Marker => break,
                    Afe::Elem(n, t) => {
                        if t.name == subject {
                            found = Some((i, *n, t.clone()));
                            break;
                        }
                    }
                }
            }
            let (fe_afe_idx, fe, fe_tag) = match found {
                Some(x) => x,
                None => {
                    self.any_other_end_tag_in_body(subject);
                    return;
                }
            };
            let fe_stack_idx = match self.open.iter().rposition(|&n| n == fe) {
                Some(i) => i,
                None => {
                    self.afe.remove(fe_afe_idx);
                    return;
                }
            };
            if !self.in_scope_node(fe, Scope::Default) {
                return;
            }
            // 9. furthest block
            let mut fb = None;
            for i in fe_stack_idx..self.open.len() {
                if self.is_special(self.open[i]) {
                    fb = Some((i, self.open[i]));
                    break;
                }
            }
            let (fb_idx, furthest_block) = match fb {
                Some(x) => x,
                None => {
                    self.open.truncate(fe_stack_idx);
                    self.afe.remove(fe_afe_idx);
                    return;
                }
            };
            let common_ancestor = self.open[fe_stack_idx - 1];
            // bookmark: None => replace fe; Some(n) => insert after n
            let mut bookmark: Option<NodeId> = None;
            let mut node_index = fb_idx;
            let mut last_node = furthest_block;
            let mut inner = 0;
            loop {
                inner += 1;
                node_index -= 1;
                let mut node = self.open[node_index];
                if node == fe {
                    break;
                }
                if inner > 3 {
                    if let Some(p) = self.afe_position(node) {
                        self.afe.remove(p);
                    }
                    self.open.remove(node_index);
                    continue;
                }
                let nfi = match self.afe_position(node) {
                    Some(i) => i,
                    None => {
                        self.open.remove(node_index);
                        continue;
                    }
                };
                let t = match &self.afe[nfi] {
                    Afe::Elem(_, t) => t.clone(),
                    Afe::Marker => unreachable!(),
                };
                let new_el = self.create_html_element_for(&t);
                self.open[node_index] = new_el;
                self.afe[nfi] = Afe::Elem(new_el, t);
                node = new_el;
                if last_node == furthest_block {
                    bookmark = Some(node);
                }
                self.dom.detach(last_node);
                self.dom.append(node, last_node);
                last_node = node;
            }
            // 14.
            self.dom.detach(last_node);
            let place = self.appropriate_place(Some(common_ancestor));
            self.insert_node_at(place, last_node);
            // 15.
            let new_el = self.create_html_element_for(&fe_tag);
            // 16.
            let children = self.dom.children(furthest_block);
            for c in children {
                self.dom.append(new_el, c);
            }
            // 17.
            self.dom.append(furthest_block, new_el);
            // 18.
            match bookmark {
                None => {
                    let idx = self.afe_position(fe).unwrap();
                    self.afe[idx] = Afe::Elem(new_el, fe_tag);
                }
                Some(prev) => {
                    let idx = self.afe_position(prev).unwrap() + 1;
                    self.afe.insert(idx, Afe::Elem(new_el, fe_tag));
                    let old = self.afe_position(fe).unwrap();
                    self.afe.remove(old);
                }
            }
            // 19.
            self.remove_from_stack(fe);
            let nfb = self.open.iter().position(|&n| n == furthest_block).unwrap();
            self.open.insert(nfb + 1, new_el);
        }
    }

    fn any_other_end_tag_in_body(&mut self, name: &str) {
        let mut match_idx = None;
        for i in (0..self.open.len()).rev() {
            let n = self.open[i];
            if self.is_html_named(n, name) {
                match_idx = Some(i);
                break;
            }
            if self.is_special(n) {
                return;
            }
        }
        let idx = match match_idx {
            Some(i) => i,
            None => return,
        };
        self.generate_implied_end(Some(name));
        self.open.truncate(idx);
    }

    fn reset_insertion_mode(&mut self) {
        let mut i = self.open.len();
        while i > 0 {
            i -= 1;
            let node = self.open[i];
            let last = i == 0;
            let e = self.elem(node);
            if e.ns != NS_HTML {
                if last {
                    self.mode = Mode::InBody;
                    return;
                }
                continue;
            }
            match e.local.as_str() {
                "select" => {
                    if !last {
                        let mut j = i;
                        while j > 0 {
                            j -= 1;
                            let anc = self.open[j];
                            if self.is_html_named(anc, "template") {
                                break;
                            }
                            if self.is_html_named(anc, "table") {
                                self.mode = Mode::InSelectInTable;
                                return;
                            }
                        }
                    }
                    self.mode = Mode::InSelect;
                    return;
                }
                "td" | "th" if !last => {
                    self.mode = Mode::InCell;
                    return;
                }
                "tr" => {
                    self.mode = Mode::InRow;
                    return;
                }
                "tbody" | "thead" | "tfoot" => {
                    self.mode = Mode::InTableBody;
                    return;
                }
                "caption" => {
                    self.mode = Mode::InCaption;
                    return;
                }
                "colgroup" => {
                    self.mode = Mode::InColumnGroup;
                    return;
                }
                "table" => {
                    self.mode = Mode::InTable;
                    return;
                }
                "template" => {
                    self.mode = *self.template_modes.last().unwrap_or(&Mode::InBody);
                    return;
                }
                "head" if !last => {
                    self.mode = Mode::InHead;
                    return;
                }
                "body" => {
                    self.mode = Mode::InBody;
                    return;
                }
                "frameset" => {
                    self.mode = Mode::InFrameset;
                    return;
                }
                "html" => {
                    self.mode = if self.head.is_none() { Mode::BeforeHead } else { Mode::AfterHead };
                    return;
                }
                _ => {}
            }
            if last {
                self.mode = Mode::InBody;
                return;
            }
        }
        self.mode = Mode::InBody;
    }

    // ---------- dispatch ----------

    fn is_foreign(&self, tok: &Token) -> bool {
        if let Token::Eof = tok {
            return false;
        }
        let cur = match self.open.last() {
            Some(&c) => c,
            None => return false,
        };
        let e = self.elem(cur);
        if e.ns == NS_HTML {
            return false;
        }
        if self.is_mathml_text_integration_point(cur) {
            match tok {
                Token::Char(_) => return false,
                Token::StartTag(t) if t.name != "mglyph" && t.name != "malignmark" => return false,
                _ => {}
            }
        }
        if self.is_html_integration_point(cur) {
            match tok {
                Token::Char(_) | Token::StartTag(_) => return false,
                _ => {}
            }
        }
        if e.ns == NS_MATHML && e.local == "annotation-xml" {
            if let Token::StartTag(t) = tok {
                if t.name == "svg" {
                    return false;
                }
            }
        }
        true
    }

    fn step(&mut self, mode: Mode, tok: Token) -> Step {
        match mode {
            Mode::Initial => self.initial(tok),
            Mode::BeforeHtml => self.before_html(tok),
            Mode::BeforeHead => self.before_head(tok),
            Mode::InHead => self.in_head(tok),
            Mode::InHeadNoscript => self.in_head_noscript(tok),
            Mode::AfterHead => self.after_head(tok),
            Mode::InBody => self.in_body(tok),
            Mode::Text => self.text_mode(tok),
            Mode::InTable => self.in_table(tok),
            Mode::InTableText => self.in_table_text(tok),
            Mode::InCaption => self.in_caption(tok),
            Mode::InColumnGroup => self.in_column_group(tok),
            Mode::InTableBody => self.in_table_body(tok),
            Mode::InRow => self.in_row(tok),
            Mode::InCell => self.in_cell(tok),
            Mode::InSelect => self.in_select(tok),
            Mode::InSelectInTable => self.in_select_in_table(tok),
            Mode::InTemplate => self.in_template(tok),
            Mode::AfterBody => self.after_body(tok),
            Mode::InFrameset => self.in_frameset(tok),
            Mode::AfterFrameset => self.after_frameset(tok),
            Mode::AfterAfterBody => self.after_after_body(tok),
            Mode::AfterAfterFrameset => self.after_after_frameset(tok),
        }
    }

    fn set_quirks_from_doctype(&mut self, d: &Doctype) {
        let name_ok = d.name.as_deref() == Some("html");
        let public = d.public_id.as_ref().map(|s| s.to_ascii_lowercase());
        let system = d.system_id.as_ref().map(|s| s.to_ascii_lowercase());
        let p = public.as_deref();
        let quirks = d.force_quirks
            || !name_ok
            || p == Some("-//w3o//dtd w3 html strict 3.0//en//")
            || p == Some("-/w3c/dtd html 4.0 transitional/en")
            || p == Some("html")
            || system.as_deref() == Some("http://www.ibm.com/data/dtd/v11/ibmxhtml1-transitional.dtd")
            || p.map(|p| QUIRKY_PUBLIC_PREFIXES.iter().any(|pre| p.starts_with(pre))).unwrap_or(false)
            || (system.is_none()
                && p.map(|p| {
                    p.starts_with("-//w3c//dtd html 4.01 frameset//")
                        || p.starts_with("-//w3c//dtd html 4.01 transitional//")
                })
                .unwrap_or(false));
        if quirks {
            self.quirks = Quirks::Quirks;
            return;
        }
        let limited = p
            .map(|p| p.starts_with("-//w3c//dtd xhtml 1.0 frameset//") || p.starts_with("-//w3c//dtd xhtml 1.0 transitional//"))
            .unwrap_or(false)
            || (system.is_some()
                && p.map(|p| {
                    p.starts_with("-//w3c//dtd html 4.01 frameset//")
                        || p.starts_with("-//w3c//dtd html 4.01 transitional//")
                })
                .unwrap_or(false));
        if limited {
            self.quirks = Quirks::Limited;
        }
    }

    fn initial(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char(c) if is_ws_char(c) => Done,
            Token::Comment(text) => {
                self.append_comment_to(DOCUMENT, text);
                Done
            }
            Token::Doctype(d) => {
                let node = self.dom.new_node(NodeData::Doctype {
                    name: d.name.clone().unwrap_or_default(),
                    public_id: d.public_id.clone().unwrap_or_default(),
                    system_id: d.system_id.clone().unwrap_or_default(),
                });
                self.dom.append(DOCUMENT, node);
                self.set_quirks_from_doctype(&d);
                self.mode = Mode::BeforeHtml;
                Done
            }
            tok => {
                self.quirks = Quirks::Quirks;
                self.mode = Mode::BeforeHtml;
                Reprocess(tok)
            }
        }
    }

    fn before_html(&mut self, tok: Token) -> Step {
        match tok {
            Token::Doctype(_) => Done,
            Token::Comment(text) => {
                self.append_comment_to(DOCUMENT, text);
                Done
            }
            Token::Char(c) if is_ws_char(c) => Done,
            Token::StartTag(t) if t.name == "html" => {
                let node = self.create_html_element_for(&t);
                self.dom.append(DOCUMENT, node);
                self.open.push(node);
                self.mode = Mode::BeforeHead;
                Done
            }
            Token::EndTag(t) if !matches!(t.name.as_str(), "head" | "body" | "html" | "br") => Done,
            tok => {
                let node = self.create_element(NS_HTML, "html", Vec::new());
                self.dom.append(DOCUMENT, node);
                self.open.push(node);
                self.mode = Mode::BeforeHead;
                Reprocess(tok)
            }
        }
    }

    fn before_head(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char(c) if is_ws_char(c) => Done,
            Token::Comment(text) => {
                self.insert_comment(text);
                Done
            }
            Token::Doctype(_) => Done,
            Token::StartTag(ref t) if t.name == "html" => self.in_body(tok),
            Token::StartTag(t) if t.name == "head" => {
                let node = self.insert_html_element(&t);
                self.head = Some(node);
                self.mode = Mode::InHead;
                Done
            }
            Token::EndTag(t) if !matches!(t.name.as_str(), "head" | "body" | "html" | "br") => Done,
            tok => {
                let node = self.insert_html_element(&tag("head"));
                self.head = Some(node);
                self.mode = Mode::InHead;
                Reprocess(tok)
            }
        }
    }

    fn generic_text(&mut self, t: &Tag, state: State) {
        self.insert_html_element(t);
        self.next_state = Some(state);
        self.orig_mode = self.mode;
        self.mode = Mode::Text;
    }

    fn in_head(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char(c) if is_ws_char(c) => {
                self.insert_char(c);
                Done
            }
            Token::Comment(text) => {
                self.insert_comment(text);
                Done
            }
            Token::Doctype(_) => Done,
            Token::StartTag(ref t) if t.name == "html" => self.in_body(tok),
            Token::StartTag(t) if matches!(t.name.as_str(), "base" | "basefont" | "bgsound" | "link" | "meta") => {
                self.insert_html_element(&t);
                self.pop();
                Done
            }
            Token::StartTag(t) if t.name == "title" => {
                self.generic_text(&t, State::Rcdata);
                Done
            }
            Token::StartTag(t) if t.name == "noscript" && self.scripting => {
                self.generic_text(&t, State::Rawtext);
                Done
            }
            Token::StartTag(t) if t.name == "noframes" || t.name == "style" => {
                self.generic_text(&t, State::Rawtext);
                Done
            }
            Token::StartTag(t) if t.name == "noscript" => {
                self.insert_html_element(&t);
                self.mode = Mode::InHeadNoscript;
                Done
            }
            Token::StartTag(t) if t.name == "script" => {
                self.generic_text(&t, State::ScriptData);
                Done
            }
            Token::EndTag(t) if t.name == "head" => {
                self.pop();
                self.mode = Mode::AfterHead;
                Done
            }
            Token::StartTag(t) if t.name == "template" => {
                self.insert_html_element(&t);
                self.afe.push(Afe::Marker);
                self.frameset_ok = false;
                self.mode = Mode::InTemplate;
                self.template_modes.push(Mode::InTemplate);
                Done
            }
            Token::EndTag(t) if t.name == "template" => {
                if !self.stack_has("template") {
                    return Done;
                }
                self.generate_implied_end_thorough();
                self.pop_until("template");
                self.clear_afe_to_marker();
                self.template_modes.pop();
                self.reset_insertion_mode();
                Done
            }
            Token::StartTag(t) if t.name == "head" => Done,
            Token::EndTag(t) if !matches!(t.name.as_str(), "body" | "html" | "br") => Done,
            tok => {
                self.pop();
                self.mode = Mode::AfterHead;
                Reprocess(tok)
            }
        }
    }

    fn in_head_noscript(&mut self, tok: Token) -> Step {
        match tok {
            Token::Doctype(_) => Done,
            Token::StartTag(ref t) if t.name == "html" => self.in_body(tok),
            Token::EndTag(t) if t.name == "noscript" => {
                self.pop();
                self.mode = Mode::InHead;
                Done
            }
            Token::Char(c) if is_ws_char(c) => self.in_head(Token::Char(c)),
            Token::Comment(_) => self.in_head(tok),
            Token::StartTag(ref t)
                if matches!(t.name.as_str(), "basefont" | "bgsound" | "link" | "meta" | "noframes" | "style") =>
            {
                self.in_head(tok)
            }
            Token::StartTag(t) if t.name == "head" || t.name == "noscript" => Done,
            Token::EndTag(t) if t.name != "br" => Done,
            tok => {
                self.pop();
                self.mode = Mode::InHead;
                Reprocess(tok)
            }
        }
    }

    fn after_head(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char(c) if is_ws_char(c) => {
                self.insert_char(c);
                Done
            }
            Token::Comment(text) => {
                self.insert_comment(text);
                Done
            }
            Token::Doctype(_) => Done,
            Token::StartTag(ref t) if t.name == "html" => self.in_body(tok),
            Token::StartTag(t) if t.name == "body" => {
                self.insert_html_element(&t);
                self.frameset_ok = false;
                self.mode = Mode::InBody;
                Done
            }
            Token::StartTag(t) if t.name == "frameset" => {
                self.insert_html_element(&t);
                self.mode = Mode::InFrameset;
                Done
            }
            Token::StartTag(ref t)
                if matches!(
                    t.name.as_str(),
                    "base" | "basefont" | "bgsound" | "link" | "meta" | "noframes" | "script" | "style" | "template"
                        | "title"
                ) =>
            {
                let head = self.head.unwrap();
                self.open.push(head);
                let r = self.in_head(tok);
                self.remove_from_stack(head);
                r
            }
            Token::EndTag(ref t) if t.name == "template" => self.in_head(tok),
            Token::StartTag(t) if t.name == "head" => Done,
            Token::EndTag(t) if !matches!(t.name.as_str(), "body" | "html" | "br") => Done,
            tok => {
                self.insert_html_element(&tag("body"));
                self.mode = Mode::InBody;
                Reprocess(tok)
            }
        }
    }

    fn in_body(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char('\0') => Done,
            Token::Char(c) => {
                self.reconstruct_formatting();
                self.insert_char(c);
                if !is_ws_char(c) {
                    self.frameset_ok = false;
                }
                Done
            }
            Token::Comment(text) => {
                self.insert_comment(text);
                Done
            }
            Token::Doctype(_) => Done,
            Token::Eof => {
                if !self.template_modes.is_empty() {
                    return self.in_template(Token::Eof);
                }
                Done
            }
            Token::StartTag(t) => self.in_body_start(t),
            Token::EndTag(t) => self.in_body_end(t),
        }
    }

    fn in_body_start(&mut self, t: Tag) -> Step {
        let name = t.name.as_str();
        match name {
            "html" => {
                if self.stack_has("template") {
                    return Done;
                }
                let top = self.open[0];
                let e = self.dom.element_mut(top).unwrap();
                for (n, v) in &t.attrs {
                    e.insert_attr_if_missing(Attr { ns: NS_NONE, local: n.clone(), prefix: None, value: v.clone() });
                }
                Done
            }
            "base" | "basefont" | "bgsound" | "link" | "meta" | "noframes" | "script" | "style" | "template"
