    fn in_body_end(&mut self, t: Tag) -> Step {
        let name = t.name.as_str();
        match name {
            "template" => self.in_head(Token::EndTag(t)),
            "body" => {
                if !self.in_scope("body", Scope::Default) {
                    return Done;
                }
                self.mode = Mode::AfterBody;
                Done
            }
            "html" => {
                if !self.in_scope("body", Scope::Default) {
                    return Done;
                }
                self.mode = Mode::AfterBody;
                Reprocess(Token::EndTag(t))
            }
            "address" | "article" | "aside" | "blockquote" | "button" | "center" | "details" | "dialog" | "dir"
            | "div" | "dl" | "fieldset" | "figcaption" | "figure" | "footer" | "header" | "hgroup" | "listing"
            | "main" | "menu" | "nav" | "ol" | "pre" | "section" | "summary" | "ul" => {
                if !self.in_scope(name, Scope::Default) {
                    return Done;
                }
                self.generate_implied_end(None);
                self.pop_until(name);
                Done
            }
            "form" => {
                if !self.stack_has("template") {
                    let node = self.form.take();
                    let node = match node {
                        Some(n) => n,
                        None => return Done,
                    };
                    if !self.in_scope_node(node, Scope::Default) {
                        return Done;
                    }
                    self.generate_implied_end(None);
                    self.remove_from_stack(node);
                    Done
                } else {
                    if !self.in_scope("form", Scope::Default) {
                        return Done;
                    }
                    self.generate_implied_end(None);
                    self.pop_until("form");
                    Done
                }
            }
            "p" => {
                if !self.in_scope("p", Scope::Button) {
                    self.insert_html_element(&tag("p"));
                }
                self.close_p_element();
                Done
            }
            "li" => {
                if !self.in_scope("li", Scope::ListItem) {
                    return Done;
                }
                self.generate_implied_end(Some("li"));
                self.pop_until("li");
                Done
            }
            "dd" | "dt" => {
                if !self.in_scope(name, Scope::Default) {
                    return Done;
                }
                self.generate_implied_end(Some(name));
                self.pop_until(name);
                Done
            }
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                let hs = ["h1", "h2", "h3", "h4", "h5", "h6"];
                if !self.in_scope_any(&hs, Scope::Default) {
                    return Done;
                }
                self.generate_implied_end(None);
                self.pop_until_any(&hs);
                Done
            }
            "a" | "b" | "big" | "code" | "em" | "font" | "i" | "nobr" | "s" | "small" | "strike" | "strong"
            | "tt" | "u" => {
                let n = name.to_string();
                self.adoption_agency(&n);
                Done
            }
            "applet" | "marquee" | "object" => {
                if !self.in_scope(name, Scope::Default) {
                    return Done;
                }
                self.generate_implied_end(None);
                self.pop_until(name);
                self.clear_afe_to_marker();
                Done
            }
            "br" => self.in_body_start(Tag { name: "br".to_string(), attrs: Vec::new(), self_closing: false }),
            _ => {
                let n = name.to_string();
                self.any_other_end_tag_in_body(&n);
                Done
            }
        }
    }

    fn text_mode(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char(c) => {
                self.insert_char(c);
                Done
            }
            Token::Eof => {
                self.pop();
                self.mode = self.orig_mode;
                Reprocess(Token::Eof)
            }
            Token::EndTag(_) => {
                self.pop();
                self.mode = self.orig_mode;
                Done
            }
            _ => Done,
        }
    }

    fn clear_to_table_context(&mut self) {
        while !self.current_in(&["table", "template", "html"]) {
            self.pop();
        }
    }

    fn clear_to_table_body_context(&mut self) {
        while !self.current_in(&["tbody", "tfoot", "thead", "template", "html"]) {
