    fn foster_in_body(&mut self, tok: Token) -> Step {
        self.foster_parenting = true;
        let r = self.in_body(tok);
        self.foster_parenting = false;
        r
    }

    fn in_table(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char(_) if self.current_in(&["table", "tbody", "template", "tfoot", "thead", "tr"]) => {
                self.pending_chars.clear();
                self.orig_mode = self.mode;
                self.mode = Mode::InTableText;
                Reprocess(tok)
            }
            Token::Comment(text) => {
                self.insert_comment(text);
                Done
            }
            Token::Doctype(_) => Done,
            Token::StartTag(t) if t.name == "caption" => {
                self.clear_to_table_context();
                self.afe.push(Afe::Marker);
                self.insert_html_element(&t);
                self.mode = Mode::InCaption;
                Done
            }
            Token::StartTag(t) if t.name == "colgroup" => {
                self.clear_to_table_context();
                self.insert_html_element(&t);
                self.mode = Mode::InColumnGroup;
                Done
            }
            Token::StartTag(t) if t.name == "col" => {
                self.clear_to_table_context();
                self.insert_html_element(&tag("colgroup"));
                self.mode = Mode::InColumnGroup;
                Reprocess(Token::StartTag(t))
            }
            Token::StartTag(t) if matches!(t.name.as_str(), "tbody" | "tfoot" | "thead") => {
                self.clear_to_table_context();
                self.insert_html_element(&t);
                self.mode = Mode::InTableBody;
                Done
            }
            Token::StartTag(t) if matches!(t.name.as_str(), "td" | "th" | "tr") => {
                self.clear_to_table_context();
                self.insert_html_element(&tag("tbody"));
                self.mode = Mode::InTableBody;
                Reprocess(Token::StartTag(t))
            }
            Token::StartTag(t) if t.name == "table" => {
                if !self.in_scope("table", Scope::Table) {
                    return Done;
                }
                self.pop_until("table");
                self.reset_insertion_mode();
                Reprocess(Token::StartTag(t))
            }
            Token::EndTag(t) if t.name == "table" => {
                if !self.in_scope("table", Scope::Table) {
                    return Done;
                }
                self.pop_until("table");
                self.reset_insertion_mode();
                Done
            }
            Token::EndTag(t)
                if matches!(
                    t.name.as_str(),
                    "body" | "caption" | "col" | "colgroup" | "html" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr"
                ) =>
            {
                Done
            }
            Token::StartTag(ref t) if matches!(t.name.as_str(), "style" | "script" | "template") => self.in_head(tok),
            Token::EndTag(ref t) if t.name == "template" => self.in_head(tok),
            Token::StartTag(t)
                if t.name == "input"
                    && t.attrs.iter().any(|(n, v)| n == "type" && v.eq_ignore_ascii_case("hidden")) =>
            {
                self.insert_html_element(&t);
                self.pop();
                Done
            }
            Token::StartTag(t) if t.name == "form" => {
                if self.stack_has("template") || self.form.is_some() {
                    return Done;
                }
                let node = self.insert_html_element(&t);
                self.form = Some(node);
                self.pop();
                Done
            }
            Token::Eof => self.in_body(tok),
            tok => self.foster_in_body(tok),
        }
    }

    fn in_table_text(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char('\0') => Done,
            Token::Char(c) => {
                self.pending_chars.push(c);
                Done
            }
            tok => {
                let pending = std::mem::take(&mut self.pending_chars);
                if pending.iter().any(|&c| !is_ws_char(c)) {
                    for c in pending {
                        self.foster_in_body(Token::Char(c));
                    }
                } else {
                    for c in pending {
                        self.insert_char(c);
                    }
                }
                self.mode = self.orig_mode;
                Reprocess(tok)
            }
        }
    }

    fn close_caption(&mut self) -> bool {
