    fn in_column_group(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char(c) if is_ws_char(c) => {
                self.insert_char(c);
                Done
            }
            Token::Comment(text) => {
                self.insert_comment(text);
                Done
            }
            Token::Doctype(_) => Done,
            Token::StartTag(ref t) if t.name == "html" => self.in_body(tok),
            Token::StartTag(t) if t.name == "col" => {
                self.insert_html_element(&t);
                self.pop();
                Done
            }
            Token::EndTag(t) if t.name == "colgroup" => {
                if !self.current_is("colgroup") {
                    return Done;
                }
                self.pop();
                self.mode = Mode::InTable;
                Done
            }
            Token::EndTag(t) if t.name == "col" => Done,
            Token::StartTag(ref t) if t.name == "template" => self.in_head(tok),
            Token::EndTag(ref t) if t.name == "template" => self.in_head(tok),
            Token::Eof => self.in_body(tok),
            tok => {
                if !self.current_is("colgroup") {
                    return Done;
                }
                self.pop();
                self.mode = Mode::InTable;
                Reprocess(tok)
            }
        }
    }

    fn in_table_body(&mut self, tok: Token) -> Step {
        match tok {
            Token::StartTag(t) if t.name == "tr" => {
                self.clear_to_table_body_context();
                self.insert_html_element(&t);
                self.mode = Mode::InRow;
