            }
            Token::StartTag(t) if t.name == "th" || t.name == "td" => {
                self.clear_to_table_body_context();
                self.insert_html_element(&tag("tr"));
                self.mode = Mode::InRow;
                Reprocess(Token::StartTag(t))
            }
            Token::EndTag(t) if matches!(t.name.as_str(), "tbody" | "tfoot" | "thead") => {
                if !self.in_scope(&t.name, Scope::Table) {
                    return Done;
                }
                self.clear_to_table_body_context();
                self.pop();
                self.mode = Mode::InTable;
                Done
            }
            Token::StartTag(ref t)
                if matches!(t.name.as_str(), "caption" | "col" | "colgroup" | "tbody" | "tfoot" | "thead") =>
            {
                self.table_body_exit(tok)
            }
            Token::EndTag(ref t) if t.name == "table" => self.table_body_exit(tok),
            Token::EndTag(t)
                if matches!(
                    t.name.as_str(),
                    "body" | "caption" | "col" | "colgroup" | "html" | "td" | "th" | "tr"
                ) =>
            {
                Done
            }
            tok => self.in_table(tok),
        }
    }

    fn table_body_exit(&mut self, tok: Token) -> Step {
        if !self.in_scope_any(&["tbody", "thead", "tfoot"], Scope::Table) {
            return Done;
