                }
                self.clear_to_table_row_context();
                self.pop();
                self.mode = Mode::InTableBody;
                Done
            }
            Token::StartTag(ref t)
                if matches!(t.name.as_str(), "caption" | "col" | "colgroup" | "tbody" | "tfoot" | "thead" | "tr") =>
            {
                self.row_exit(tok)
            }
            Token::EndTag(ref t) if t.name == "table" => self.row_exit(tok),
            Token::EndTag(ref t) if matches!(t.name.as_str(), "tbody" | "tfoot" | "thead") => {
                if !self.in_scope(&t.name, Scope::Table) {
                    return Done;
                }
                self.row_exit(tok)
            }
            Token::EndTag(t)
                if matches!(t.name.as_str(), "body" | "caption" | "col" | "colgroup" | "html" | "td" | "th") =>
            {
                Done
            }
            tok => self.in_table(tok),
        }
    }

    fn row_exit(&mut self, tok: Token) -> Step {
        if !self.in_scope("tr", Scope::Table) {
            return Done;
        }
        self.clear_to_table_row_context();
        self.pop();
