    fn in_cell(&mut self, tok: Token) -> Step {
        match tok {
            Token::EndTag(t) if t.name == "td" || t.name == "th" => {
                if !self.in_scope(&t.name, Scope::Table) {
                    return Done;
                }
                self.generate_implied_end(None);
                self.pop_until(&t.name);
                self.clear_afe_to_marker();
                self.mode = Mode::InRow;
                Done
            }
            Token::StartTag(ref t)
                if matches!(
                    t.name.as_str(),
                    "caption" | "col" | "colgroup" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr"
                ) =>
            {
                if !self.in_scope_any(&["td", "th"], Scope::Table) {
                    return Done;
                }
                self.close_cell();
                Reprocess(tok)
            }
            Token::EndTag(t) if matches!(t.name.as_str(), "body" | "caption" | "col" | "colgroup" | "html") => Done,
            Token::EndTag(ref t) if matches!(t.name.as_str(), "table" | "tbody" | "tfoot" | "thead" | "tr") => {
                if !self.in_scope(&t.name, Scope::Table) {
                    return Done;
                }
                self.close_cell();
                Reprocess(tok)
            }
            tok => self.in_body(tok),
        }
    }

    fn in_select(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char('\0') => Done,
            Token::Char(c) => {
                self.insert_char(c);
                Done
            }
            Token::Comment(text) => {
                self.insert_comment(text);
                Done
            }
            Token::Doctype(_) => Done,
            Token::StartTag(ref t) if t.name == "html" => self.in_body(tok),
            Token::StartTag(t) if t.name == "option" => {
                if self.current_is("option") {
                    self.pop();
                }
                self.insert_html_element(&t);
                Done
            }
            Token::StartTag(t) if t.name == "optgroup" => {
                if self.current_is("option") {
                    self.pop();
                }
                if self.current_is("optgroup") {
                    self.pop();
                }
                self.insert_html_element(&t);
                Done
            }
            Token::EndTag(t) if t.name == "optgroup" => {
                if self.current_is("option") && self.open.len() >= 2 {
                    let before = self.open[self.open.len() - 2];
                    if self.is_html_named(before, "optgroup") {
                        self.pop();
                    }
                }
                if self.current_is("optgroup") {
                    self.pop();
                }
                Done
            }
            Token::EndTag(t) if t.name == "option" => {
                if self.current_is("option") {
                    self.pop();
                }
                Done
            }
            Token::EndTag(t) if t.name == "select" => {
                if !self.in_scope("select", Scope::Select) {
                    return Done;
                }
                self.pop_until("select");
                self.reset_insertion_mode();
                Done
            }
            Token::StartTag(t) if t.name == "select" => {
                if !self.in_scope("select", Scope::Select) {
                    return Done;
                }
                self.pop_until("select");
                self.reset_insertion_mode();
                Done
            }
            Token::StartTag(ref t) if matches!(t.name.as_str(), "input" | "keygen" | "textarea") => {
                if !self.in_scope("select", Scope::Select) {
                    return Done;
                }
                self.pop_until("select");
                self.reset_insertion_mode();
                Reprocess(tok)
            }
            Token::StartTag(ref t) if t.name == "script" || t.name == "template" => self.in_head(tok),
            Token::EndTag(ref t) if t.name == "template" => self.in_head(tok),
            Token::Eof => self.in_body(tok),
            _ => Done,
        }
    }

    fn in_select_in_table(&mut self, tok: Token) -> Step {
        const L: &[&str] = &["caption", "table", "tbody", "tfoot", "thead", "tr", "td", "th"];
        match tok {
            Token::StartTag(ref t) if L.contains(&t.name.as_str()) => {
                self.pop_until("select");
                self.reset_insertion_mode();
                Reprocess(tok)
            }
            Token::EndTag(ref t) if L.contains(&t.name.as_str()) => {
                if !self.in_scope(&t.name, Scope::Table) {
                    return Done;
                }
                self.pop_until("select");
                self.reset_insertion_mode();
                Reprocess(tok)
            }
            tok => self.in_select(tok),
        }
    }

    fn in_template(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char(_) | Token::Comment(_) | Token::Doctype(_) => self.in_body(tok),
            Token::StartTag(ref t)
                if matches!(
                    t.name.as_str(),
                    "base" | "basefont" | "bgsound" | "link" | "meta" | "noframes" | "script" | "style" | "template"
                        | "title"
                ) =>
            {
                self.in_head(tok)
            }
            Token::EndTag(ref t) if t.name == "template" => self.in_head(tok),
            Token::StartTag(ref t) if matches!(t.name.as_str(), "caption" | "colgroup" | "tbody" | "tfoot" | "thead") => {
                self.switch_template_mode(Mode::InTable, tok)
            }
            Token::StartTag(ref t) if t.name == "col" => self.switch_template_mode(Mode::InColumnGroup, tok),
            Token::StartTag(ref t) if t.name == "tr" => self.switch_template_mode(Mode::InTableBody, tok),
            Token::StartTag(ref t) if t.name == "td" || t.name == "th" => self.switch_template_mode(Mode::InRow, tok),
            Token::StartTag(_) => self.switch_template_mode(Mode::InBody, tok),
            Token::EndTag(_) => Done,
            Token::Eof => {
                if !self.stack_has("template") {
                    return Done;
                }
                self.pop_until("template");
                self.clear_afe_to_marker();
                self.template_modes.pop();
                self.reset_insertion_mode();
                Reprocess(Token::Eof)
            }
        }
    }

    fn switch_template_mode(&mut self, m: Mode, tok: Token) -> Step {
        self.template_modes.pop();
        self.template_modes.push(m);
        self.mode = m;
        Reprocess(tok)
    }

    fn after_body(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char(c) if is_ws_char(c) => self.in_body(tok),
            Token::Comment(text) => {
                let html = self.open[0];
                self.append_comment_to(html, text);
                Done
            }
            Token::Doctype(_) => Done,
            Token::StartTag(ref t) if t.name == "html" => self.in_body(tok),
            Token::EndTag(t) if t.name == "html" => {
                self.mode = Mode::AfterAfterBody;
                Done
            }
            Token::Eof => Done,
            tok => {
                self.mode = Mode::InBody;
                Reprocess(tok)
            }
        }
    }

    fn in_frameset(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char(c) if is_ws_char(c) => {
                self.insert_char(c);
                Done
            }
            Token::Comment(text) => {
                self.insert_comment(text);
                Done
            }
            Token::Doctype(_) => Done,
            Token::StartTag(ref t) if t.name == "html" => self.in_body(tok),
            Token::StartTag(t) if t.name == "frameset" => {
                self.insert_html_element(&t);
                Done
            }
            Token::EndTag(t) if t.name == "frameset" => {
                if self.open.len() == 1 && self.current_is("html") {
                    return Done;
                }
                self.pop();
                if !self.current_is("frameset") {
                    self.mode = Mode::AfterFrameset;
                }
                Done
            }
            Token::StartTag(t) if t.name == "frame" => {
                self.insert_html_element(&t);
                self.pop();
                Done
            }
            Token::StartTag(ref t) if t.name == "noframes" => self.in_head(tok),
            Token::Eof => Done,
            _ => Done,
        }
    }

    fn after_frameset(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char(c) if is_ws_char(c) => {
                self.insert_char(c);
                Done
            }
            Token::Comment(text) => {
                self.insert_comment(text);
                Done
            }
            Token::Doctype(_) => Done,
            Token::StartTag(ref t) if t.name == "html" => self.in_body(tok),
            Token::EndTag(t) if t.name == "html" => {
                self.mode = Mode::AfterAfterFrameset;
                Done
            }
            Token::StartTag(ref t) if t.name == "noframes" => self.in_head(tok),
            _ => Done,
        }
    }

    fn after_after_body(&mut self, tok: Token) -> Step {
        match tok {
            Token::Comment(text) => {
                self.append_comment_to(DOCUMENT, text);
                Done
            }
            Token::Doctype(_) => self.in_body(tok),
            Token::Char(c) if is_ws_char(c) => self.in_body(tok),
            Token::StartTag(ref t) if t.name == "html" => self.in_body(tok),
            Token::Eof => Done,
            tok => {
                self.mode = Mode::InBody;
                Reprocess(tok)
            }
        }
    }

    fn after_after_frameset(&mut self, tok: Token) -> Step {
        match tok {
            Token::Comment(text) => {
                self.append_comment_to(DOCUMENT, text);
                Done
            }
            Token::Doctype(_) => self.in_body(tok),
            Token::Char(c) if is_ws_char(c) => self.in_body(tok),
            Token::StartTag(ref t) if t.name == "html" => self.in_body(tok),
            Token::Eof => Done,
            Token::StartTag(ref t) if t.name == "noframes" => self.in_head(tok),
            _ => Done,
        }
    }

    fn foreign_content(&mut self, tok: Token) -> Step {
        match tok {
            Token::Char('\0') => {
                self.insert_char('\u{FFFD}');
                Done
            }
            Token::Char(c) => {
                self.insert_char(c);
                if !is_ws_char(c) {
                    self.frameset_ok = false;
                }
                Done
            }
            Token::Comment(text) => {
                self.insert_comment(text);
                Done
            }
            Token::Doctype(_) => Done,
            Token::StartTag(t) => {
                let breakout = matches!(
                    t.name.as_str(),
                    "b" | "big" | "blockquote" | "body" | "br" | "center" | "code" | "dd" | "div" | "dl" | "dt"
                        | "em" | "embed" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6" | "head" | "hr" | "i" | "img"
                        | "li" | "listing" | "menu" | "meta" | "nobr" | "ol" | "p" | "pre" | "ruby" | "s" | "small"
                        | "span" | "strong" | "strike" | "sub" | "sup" | "table" | "tt" | "u" | "ul" | "var"
                ) || (t.name == "font"
                    && t.attrs.iter().any(|(n, _)| n == "color" || n == "face" || n == "size"));
                if breakout {
                    self.pop();
                    loop {
                        let cur = self.current();
                        if self.elem(cur).ns == NS_HTML
                            || self.is_mathml_text_integration_point(cur)
                            || self.is_html_integration_point(cur)
                        {
                            break;
                        }
                        self.pop();
                    }
                    return Reprocess(Token::StartTag(t));
                }
                let cur = self.current();
                let ns = self.elem(cur).ns;
                let mut t = t;
                if ns == NS_SVG {
                    if let Some(&(_, adj)) = SVG_TAG_ADJUST.iter().find(|(a, _)| *a == t.name) {
                        t.name = adj.to_string();
                    }
                }
                self.insert_foreign_element(&t, ns);
                if t.self_closing {
                    self.pop();
                }
                Done
            }
            Token::EndTag(t) => {
                let cur = self.current();
                if t.name == "script" {
                    let e = self.elem(cur);
                    if e.ns == NS_SVG && e.local == "script" {
                        self.pop();
                        return Done;
                    }
                }
                let mut first = true;
                let mut idx = self.open.len() - 1;
                loop {
                    if idx == 0 {
                        return Done;
                    }
                    let node = self.open[idx];
                    let (html, eq) = {
                        let e = self.elem(node);
                        (e.ns == NS_HTML, e.local.eq_ignore_ascii_case(&t.name))
                    };
                    if !first && html {
                        return self.step(self.mode, Token::EndTag(t));
                    }
                    if eq {
                        self.open.truncate(idx);
                        return Done;
                    }
                    first = false;
                    idx -= 1;
                }
            }
            Token::Eof => Done,
        }
    }
}

#[derive(Clone, Copy)]
enum InsertionPoint {
    LastChild(NodeId),
    Foster { table: NodeId, prev: NodeId },
}

fn tags_equiv(a: &Tag, b: &Tag) -> bool {
    if a.name != b.name || a.attrs.len() != b.attrs.len() {
        return false;
    }
    let mut x = a.attrs.clone();
    let mut y = b.attrs.clone();
    x.sort();
    y.sort();
    x == y
}
