fn tags_equiv(a: &Tag, b: &Tag) -> bool {
    if a.name != b.name || a.attrs.len() != b.attrs.len() {
        return false;
    }
    let mut x = a.attrs.clone();
    let mut y = b.attrs.clone();
    x.sort();
    y.sort();
    x == y
}
