pub fn escape_into(out: &mut String, text: &str, attr_mode: bool) {
    for c in text.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '\u{00A0}' => out.push_str("&nbsp;"),
            '"' if attr_mode => out.push_str("&quot;"),
            '<' if !attr_mode => out.push_str("&lt;"),
            '>' if !attr_mode => out.push_str("&gt;"),
            c => out.push(c),
        }
    }
}

fn write_start_tag(out: &mut String, e: &ElementData) {
    out.push('<');
    out.push_str(&e.local);
    for a in &e.attrs {
        out.push(' ');
        if a.ns == NS_NONE {
        } else if a.ns == NS_XML {
            out.push_str("xml:");
        } else if a.ns == NS_XMLNS {
            if a.local != "xmlns" {
                out.push_str("xmlns:");
            }
        } else if a.ns == NS_XLINK {
            out.push_str("xlink:");
        } else {
            out.push_str("unknown_namespace:");
        }
        out.push_str(&a.local);
        out.push_str("=\"");
        escape_into(out, &a.value, true);
        out.push('"');
    }
    out.push('>');
}

