pub fn escape_into(out: &mut String, text: &str, attr_mode: bool) {
    for c in text.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '\u{00A0}' => out.push_str("&nbsp;"),
            '"' if attr_mode => out.push_str("&quot;"),
            '<' if !attr_mode => out.push_str("&lt;"),
            '>' if !attr_mode => out.push_str("&gt;"),
            c => out.push(c),
        }
    }
}

fn write_start_tag(out: &mut String, e: &ElementData) {
    out.push('<');
    out.push_str(&e.local);
    for a in &e.attrs {
        out.push(' ');
        if a.ns == NS_NONE {
