//! CSS selector tokenizer, parser and matcher (cssparser + selectors semantics).

use crate::dom::*;

#[derive(Debug, Clone, PartialEq)]
pub enum Tok {
    Ident(String),
    AtKeyword(String),
    Hash(String),
    IDHash(String),
    QuotedString(String),
    UnquotedUrl(String),
    Delim(char),
    Number { has_sign: bool, int_value: Option<i32> },
    Percentage,
    Dimension { has_sign: bool, int_value: Option<i32>, unit: String },
    WhiteSpace,
    Comment,
    Colon,
    Semicolon,
    Comma,
    IncludeMatch,
    DashMatch,
    PrefixMatch,
    SuffixMatch,
    SubstringMatch,
    Cdo,
    Cdc,
    Function(String, Vec<Tok>),
    ParenBlock(Vec<Tok>),
    SquareBlock(Vec<Tok>),
    CurlyBlock(Vec<Tok>),
    BadUrl,
    BadString,
    CloseParen,
    CloseSquare,
    CloseCurly,
}

// ---------------- tokenizer ----------------

struct Lexer {
    c: Vec<char>,
    pos: usize,
}

fn is_name_start(c: char) -> bool {
    c.is_ascii_alphabetic() || c == '_' || !c.is_ascii()
}

fn is_name_char(c: char) -> bool {
    is_name_start(c) || c.is_ascii_digit() || c == '-'
}

#[derive(PartialEq, Clone, Copy)]
enum BlockKind {
    Paren,
    Square,
    Curly,
}

enum RawTok {
    Tok(Tok),
    Open(BlockKind, Option<String>),
    Close(BlockKind),
}

impl Lexer {
    fn peek(&self, off: usize) -> Option<char> {
        self.c.get(self.pos + off).copied()
    }

    fn valid_escape_at(&self, off: usize) -> bool {
        self.peek(off) == Some('\\') && !matches!(self.peek(off + 1), Some('\n') | Some('\r') | Some('\x0c'))
    }

    fn would_start_ident_at(&self, off: usize) -> bool {
        match self.peek(off) {
            Some('-') => match self.peek(off + 1) {
                Some(c) if is_name_start(c) || c == '-' => true,
                Some('\\') => self.valid_escape_at(off + 1),
                _ => false,
            },
            Some('\\') => self.valid_escape_at(off),
            Some(c) => is_name_start(c),
            None => false,
        }
    }

    fn consume_escape(&mut self) -> char {
        // the backslash has been consumed
        match self.peek(0) {
            None => '\u{FFFD}',
            Some(c) if c.is_ascii_hexdigit() => {
                let mut v: u32 = 0;
                let mut n = 0;
                while n < 6 {
                    match self.peek(0) {
                        Some(h) if h.is_ascii_hexdigit() => {
                            v = v * 16 + h.to_digit(16).unwrap();
                            self.pos += 1;
                            n += 1;
                        }
                        _ => break,
                    }
                }
                match self.peek(0) {
                    Some(' ') | Some('\t') | Some('\n') | Some('\x0c') => self.pos += 1,
                    Some('\r') => {
                        self.pos += 1;
                        if self.peek(0) == Some('\n') {
                            self.pos += 1;
                        }
                    }
                    _ => {}
                }
                if v == 0 || (0xD800..=0xDFFF).contains(&v) || v > 0x10FFFF {
                    '\u{FFFD}'
                } else {
                    char::from_u32(v).unwrap_or('\u{FFFD}')
                }
            }
            Some(c) => {
                self.pos += 1;
                if c == '\0' {
                    '\u{FFFD}'
                } else {
                    c
                }
            }
        }
    }

    fn consume_name(&mut self) -> String {
        let mut s = String::new();
        loop {
            match self.peek(0) {
                Some('\\') if self.valid_escape_at(0) => {
                    self.pos += 1;
                    s.push(self.consume_escape());
                }
                Some('\0') => {
                    self.pos += 1;
                    s.push('\u{FFFD}');
                }
                Some(c) if is_name_char(c) => {
                    self.pos += 1;
                    s.push(c);
                }
                _ => break,
            }
        }
        s
    }

    fn starts_number_at(&self, off: usize) -> bool {
        match self.peek(off) {
            Some('+') | Some('-') => match self.peek(off + 1) {
                Some(c) if c.is_ascii_digit() => true,
                Some('.') => matches!(self.peek(off + 2), Some(c) if c.is_ascii_digit()),
                _ => false,
            },
            Some('.') => matches!(self.peek(off + 1), Some(c) if c.is_ascii_digit()),
            Some(c) => c.is_ascii_digit(),
            None => false,
        }
    }

    fn consume_number(&mut self) -> Tok {
        let mut has_sign = false;
        let mut sign = 1.0f64;
        let mut text = String::new();
        match self.peek(0) {
            Some('+') => {
                has_sign = true;
                self.pos += 1;
            }
            Some('-') => {
                has_sign = true;
                sign = -1.0;
                self.pos += 1;
                text.push('-');
            }
            _ => {}
        }
        let mut is_integer = true;
        while let Some(c) = self.peek(0) {
            if c.is_ascii_digit() {
                text.push(c);
                self.pos += 1;
            } else {
                break;
            }
        }
        if self.peek(0) == Some('.') && matches!(self.peek(1), Some(c) if c.is_ascii_digit()) {
            is_integer = false;
            text.push('.');
            self.pos += 1;
            while let Some(c) = self.peek(0) {
                if c.is_ascii_digit() {
                    text.push(c);
                    self.pos += 1;
                } else {
                    break;
                }
            }
        }
        if matches!(self.peek(0), Some('e') | Some('E')) {
            let ok = match self.peek(1) {
                Some(c) if c.is_ascii_digit() => true,
                Some('+') | Some('-') => matches!(self.peek(2), Some(c) if c.is_ascii_digit()),
                _ => false,
            };
            if ok {
                is_integer = false;
                text.push('e');
                self.pos += 1;
                if let Some(c) = self.peek(0) {
                    if c == '+' || c == '-' {
                        text.push(c);
                        self.pos += 1;
                    }
                }
                while let Some(c) = self.peek(0) {
                    if c.is_ascii_digit() {
                        text.push(c);
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
            }
        }
        let _ = sign;
        let value: f64 = text.parse().unwrap_or(0.0);
        let int_value = if is_integer {
            Some(if value >= i32::MAX as f64 {
                i32::MAX
            } else if value <= i32::MIN as f64 {
                i32::MIN
            } else {
                value as i32
            })
        } else {
            None
        };
        if self.peek(0) == Some('%') {
            self.pos += 1;
            return Tok::Percentage;
        }
        if self.would_start_ident_at(0) {
            let unit = self.consume_name();
            return Tok::Dimension { has_sign, int_value, unit };
        }
        Tok::Number { has_sign, int_value }
    }

    fn consume_string(&mut self, q: char) -> Tok {
        let mut s = String::new();
        loop {
            match self.peek(0) {
                None => return Tok::QuotedString(s),
                Some(c) if c == q => {
                    self.pos += 1;
                    return Tok::QuotedString(s);
                }
                Some('\n') | Some('\r') | Some('\x0c') => {
                    return Tok::BadString;
                }
                Some('\\') => {
                    match self.peek(1) {
                        None => {
                            self.pos += 1;
                        }
                        Some('\n') | Some('\x0c') => {
                            self.pos += 2;
                        }
                        Some('\r') => {
                            self.pos += 2;
                            if self.peek(0) == Some('\n') {
                                self.pos += 1;
                            }
                        }
                        Some(_) => {
                            self.pos += 1;
                            s.push(self.consume_escape());
                        }
                    }
                }
                Some('\0') => {
                    self.pos += 1;
                    s.push('\u{FFFD}');
                }
                Some(c) => {
                    self.pos += 1;
                    s.push(c);
                }
            }
        }
    }

    fn consume_url(&mut self) -> Tok {
        // after "url(" with optional whitespace; unquoted url
        while matches!(self.peek(0), Some(' ') | Some('\t') | Some('\n') | Some('\r') | Some('\x0c')) {
            self.pos += 1;
        }
        let mut s = String::new();
        loop {
            match self.peek(0) {
                None => return Tok::UnquotedUrl(s),
                Some(')') => {
                    self.pos += 1;
                    return Tok::UnquotedUrl(s);
                }
                Some(' ') | Some('\t') | Some('\n') | Some('\r') | Some('\x0c') => {
                    while matches!(self.peek(0), Some(' ') | Some('\t') | Some('\n') | Some('\r') | Some('\x0c')) {
                        self.pos += 1;
                    }
                    match self.peek(0) {
                        None => return Tok::UnquotedUrl(s),
                        Some(')') => {
                            self.pos += 1;
                            return Tok::UnquotedUrl(s);
                        }
                        _ => {
                            self.consume_bad_url();
                            return Tok::BadUrl;
                        }
                    }
                }
                Some('"') | Some('\'') | Some('(') => {
                    self.consume_bad_url();
                    return Tok::BadUrl;
                }
                Some('\\') => {
                    if self.valid_escape_at(0) {
                        self.pos += 1;
                        s.push(self.consume_escape());
                    } else {
                        self.consume_bad_url();
                        return Tok::BadUrl;
                    }
                }
                Some(c) => {
                    self.pos += 1;
                    s.push(c);
                }
            }
        }
    }

    fn consume_bad_url(&mut self) {
        loop {
            match self.peek(0) {
                None => return,
                Some(')') => {
                    self.pos += 1;
                    return;
                }
                Some('\\') => {
                    self.pos += 1;
                    if self.peek(0).is_some() {
                        self.pos += 1;
                    }
                }
                Some(_) => self.pos += 1,
            }
        }
    }

    fn ident_like(&mut self) -> RawTok {
        let name = self.consume_name();
        if self.peek(0) == Some('(') {
            self.pos += 1;
            if name.eq_ignore_ascii_case("url") {
                // check for quoted url
                let mut i = 0;
                while matches!(self.peek(i), Some(' ') | Some('\t') | Some('\n') | Some('\r') | Some('\x0c')) {
                    i += 1;
                }
                if matches!(self.peek(i), Some('"') | Some('\'')) {
                    return RawTok::Open(BlockKind::Paren, Some(name));
                }
                return RawTok::Tok(self.consume_url());
            }
            return RawTok::Open(BlockKind::Paren, Some(name));
        }
        RawTok::Tok(Tok::Ident(name))
    }

    fn next(&mut self) -> Option<RawTok> {
        let c = self.peek(0)?;
        let t = match c {
            ' ' | '\t' | '\n' | '\r' | '\x0c' => {
                while matches!(self.peek(0), Some(' ') | Some('\t') | Some('\n') | Some('\r') | Some('\x0c')) {
                    self.pos += 1;
                }
                RawTok::Tok(Tok::WhiteSpace)
            }
            '"' | '\'' => {
                self.pos += 1;
                RawTok::Tok(self.consume_string(c))
            }
            '#' => {
                self.pos += 1;
                if matches!(self.peek(0), Some(x) if is_name_char(x)) || self.valid_escape_at(0) {
                    let is_id = self.would_start_ident_at(0);
                    let name = self.consume_name();
                    if is_id {
                        RawTok::Tok(Tok::IDHash(name))
                    } else {
                        RawTok::Tok(Tok::Hash(name))
                    }
                } else {
                    RawTok::Tok(Tok::Delim('#'))
                }
            }
            '$' => {
                self.pos += 1;
                if self.peek(0) == Some('=') {
                    self.pos += 1;
                    RawTok::Tok(Tok::SuffixMatch)
                } else {
                    RawTok::Tok(Tok::Delim('$'))
                }
            }
            '(' => {
                self.pos += 1;
                RawTok::Open(BlockKind::Paren, None)
            }
            ')' => {
                self.pos += 1;
                RawTok::Close(BlockKind::Paren)
            }
            '*' => {
                self.pos += 1;
                if self.peek(0) == Some('=') {
                    self.pos += 1;
                    RawTok::Tok(Tok::SubstringMatch)
                } else {
                    RawTok::Tok(Tok::Delim('*'))
                }
            }
            '+' => {
                if self.starts_number_at(0) {
                    RawTok::Tok(self.consume_number())
                } else {
                    self.pos += 1;
                    RawTok::Tok(Tok::Delim('+'))
                }
            }
            ',' => {
                self.pos += 1;
                RawTok::Tok(Tok::Comma)
            }
            '-' => {
                if self.starts_number_at(0) {
                    RawTok::Tok(self.consume_number())
                } else if self.would_start_ident_at(0) {
                    self.ident_like()
                } else if self.peek(1) == Some('-') && self.peek(2) == Some('>') {
                    self.pos += 3;
                    RawTok::Tok(Tok::Cdc)
                } else {
                    self.pos += 1;
                    RawTok::Tok(Tok::Delim('-'))
                }
            }
            '.' => {
                if self.starts_number_at(0) {
                    RawTok::Tok(self.consume_number())
                } else {
                    self.pos += 1;
                    RawTok::Tok(Tok::Delim('.'))
                }
            }
            '/' => {
                if self.peek(1) == Some('*') {
                    self.pos += 2;
                    loop {
                        match self.peek(0) {
                            None => break,
                            Some('*') if self.peek(1) == Some('/') => {
                                self.pos += 2;
                                break;
                            }
                            Some(_) => self.pos += 1,
                        }
                    }
                    RawTok::Tok(Tok::Comment)
                } else {
                    self.pos += 1;
                    RawTok::Tok(Tok::Delim('/'))
                }
            }
            '0'..='9' => RawTok::Tok(self.consume_number()),
            ':' => {
                self.pos += 1;
                RawTok::Tok(Tok::Colon)
            }
            ';' => {
                self.pos += 1;
                RawTok::Tok(Tok::Semicolon)
            }
            '<' => {
                if self.peek(1) == Some('!') && self.peek(2) == Some('-') && self.peek(3) == Some('-') {
                    self.pos += 4;
                    RawTok::Tok(Tok::Cdo)
                } else {
                    self.pos += 1;
                    RawTok::Tok(Tok::Delim('<'))
                }
            }
            '@' => {
                self.pos += 1;
                if self.would_start_ident_at(0) {
                    RawTok::Tok(Tok::AtKeyword(self.consume_name()))
                } else {
                    RawTok::Tok(Tok::Delim('@'))
                }
            }
            '[' => {
                self.pos += 1;
                RawTok::Open(BlockKind::Square, None)
            }
            ']' => {
                self.pos += 1;
                RawTok::Close(BlockKind::Square)
            }
            '{' => {
                self.pos += 1;
                RawTok::Open(BlockKind::Curly, None)
            }
            '}' => {
                self.pos += 1;
                RawTok::Close(BlockKind::Curly)
            }
            '\\' => {
                if self.valid_escape_at(0) {
                    self.ident_like()
                } else {
                    self.pos += 1;
                    RawTok::Tok(Tok::Delim('\\'))
                }
            }
            '^' => {
                self.pos += 1;
                if self.peek(0) == Some('=') {
                    self.pos += 1;
                    RawTok::Tok(Tok::PrefixMatch)
                } else {
                    RawTok::Tok(Tok::Delim('^'))
                }
            }
            '|' => {
                self.pos += 1;
                if self.peek(0) == Some('=') {
                    self.pos += 1;
                    RawTok::Tok(Tok::DashMatch)
                } else {
                    RawTok::Tok(Tok::Delim('|'))
                }
            }
            '~' => {
                self.pos += 1;
                if self.peek(0) == Some('=') {
                    self.pos += 1;
                    RawTok::Tok(Tok::IncludeMatch)
                } else {
                    RawTok::Tok(Tok::Delim('~'))
                }
            }
            '\0' => self.ident_like(),
            c if is_name_start(c) => self.ident_like(),
            c => {
                self.pos += 1;
                RawTok::Tok(Tok::Delim(c))
            }
        };
        Some(t)
    }
}

fn build_tree(lx: &mut Lexer, closing: Option<BlockKind>) -> Vec<Tok> {
    let mut out = Vec::new();
    while let Some(rt) = lx.next() {
        match rt {
            RawTok::Tok(t) => out.push(t),
            RawTok::Open(kind, fname) => {
                let inner = build_tree(lx, Some(kind));
                out.push(match (kind, fname) {
                    (BlockKind::Paren, Some(n)) => Tok::Function(n, inner),
                    (BlockKind::Paren, None) => Tok::ParenBlock(inner),
                    (BlockKind::Square, _) => Tok::SquareBlock(inner),
                    (BlockKind::Curly, _) => Tok::CurlyBlock(inner),
                });
            }
            RawTok::Close(kind) => {
                if Some(kind) == closing {
                    return out;
                }
                out.push(match kind {
                    BlockKind::Paren => Tok::CloseParen,
                    BlockKind::Square => Tok::CloseSquare,
                    BlockKind::Curly => Tok::CloseCurly,
                });
            }
        }
    }
    out
}

pub fn tokenize(s: &str) -> Vec<Tok> {
    // CSS preprocessing: CRLF/CR/FF handled by tokenizer as whitespace.
    let mut lx = Lexer { c: s.chars().collect(), pos: 0 };
    build_tree(&mut lx, None)
}

// ---------------- parser ----------------

struct P<'a> {
    toks: &'a [Tok],
    pos: usize,
}

type PResult<T> = Result<T, ()>;

impl<'a> P<'a> {
    fn new(toks: &'a [Tok]) -> Self {
        P { toks, pos: 0 }
    }
    fn next_including_whitespace(&mut self) -> Option<&'a Tok> {
        while self.pos < self.toks.len() {
            let t = &self.toks[self.pos];
            self.pos += 1;
            if let Tok::Comment = t {
                continue;
            }
            return Some(t);
        }
        None
    }
    fn next(&mut self) -> Option<&'a Tok> {
        loop {
            match self.next_including_whitespace() {
                Some(Tok::WhiteSpace) => continue,
                other => return other,
            }
        }
    }
    fn skip_whitespace(&mut self) {
        while self.pos < self.toks.len() {
            match &self.toks[self.pos] {
                Tok::WhiteSpace | Tok::Comment => self.pos += 1,
                _ => break,
            }
        }
    }
    fn is_exhausted(&mut self) -> bool {
        let save = self.pos;
        let r = self.next().is_none();
        self.pos = save;
        r
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Combinator {
    Descendant,
    Child,
    NextSibling,
    LaterSibling,
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum AttrOp {
    Equal,
    Includes,
    DashMatch,
    Prefix,
    Substring,
    Suffix,
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum CaseSens {
    ExplicitSensitive,
    Sensitive,
    Insensitive,
    InsensitiveIfHtml,
}

#[derive(Debug, Clone, PartialEq)]
enum NsConstraint {
    Any,
    // Only the empty namespace can be specified (no prefixes are declared).
    Empty,
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum PseudoClass {
    AnyLink,
    Link,
    Visited,
    Active,
    Focus,
    Hover,
    Enabled,
    Disabled,
    Checked,
    Indeterminate,
}

#[derive(Debug, Clone, PartialEq)]
enum Simple {
    LocalName { name: String, lower: String },
    ExplicitUniversal,
    ExplicitNoNamespace,
    Id(String),
    Class(String),
    AttrExists { ns: NsConstraint, local: String, lower: String },
    AttrValue { ns: NsConstraint, local: String, lower: String, op: AttrOp, value: String, case: CaseSens, never: bool },
    Negation(Vec<Simple>),
    FirstChild,
    LastChild,
    OnlyChild,
    Root,
    Empty,
    Scope,
    Nth { a: i32, b: i32, of_type: bool, from_end: bool },
    FirstOfType,
    LastOfType,
    OnlyOfType,
    NonTS(PseudoClass),
}

#[derive(Debug, Clone)]
pub struct Selector {
    // compounds[0] is leftmost; combinators[i] is between compounds[i] and compounds[i+1]
    compounds: Vec<Vec<Simple>>,
    combinators: Vec<Combinator>,
}

#[derive(Debug, Clone)]
pub struct SelectorList(Vec<Selector>);

const CASE_INSENSITIVE_HTML_ATTRS: &[&str] = &[
    "accept", "accept-charset", "align", "alink", "axis", "bgcolor", "charset", "checked", "clear", "codetype",
    "color", "compact", "declare", "defer", "dir", "direction", "disabled", "enctype", "face", "frame",
    "hreflang", "http-equiv", "lang", "language", "link", "media", "method", "multiple", "nohref", "noresize",
    "noshade", "nowrap", "readonly", "rel", "rev", "rules", "scope", "scrolling", "selected", "shape", "target",
    "text", "type", "valign", "valuetype", "vlink",
];

pub fn parse_selector_list(s: &str) -> PResult<SelectorList> {
    let toks = tokenize(s);
    // split at top-level commas
    let mut parts: Vec<&[Tok]> = Vec::new();
    let mut start = 0;
    for (i, t) in toks.iter().enumerate() {
        if let Tok::Comma = t {
            parts.push(&toks[start..i]);
            start = i + 1;
        }
    }
    parts.push(&toks[start..]);
    let mut out = Vec::new();
    for part in parts {
        let mut p = P::new(part);
        p.skip_whitespace();
        let sel = parse_selector(&mut p)?;
        if !p.is_exhausted() {
            return Err(());
        }
        out.push(sel);
    }
    Ok(SelectorList(out))
}

fn parse_selector(p: &mut P) -> PResult<Selector> {
    let mut compounds = Vec::new();
    let mut combinators = Vec::new();
    loop {
        let compound = match parse_compound(p)? {
            Some(c) => c,
            None => return Err(()),
        };
        compounds.push(compound);
        let mut any_ws = false;
        let comb;
        loop {
            let before = p.pos;
            match p.next_including_whitespace() {
                None => {
                    return Ok(Selector { compounds, combinators });
                }
                Some(Tok::WhiteSpace) => any_ws = true,
                Some(Tok::Delim('>')) => {
                    comb = Combinator::Child;
                    break;
                }
                Some(Tok::Delim('+')) => {
                    comb = Combinator::NextSibling;
                    break;
                }
                Some(Tok::Delim('~')) => {
                    comb = Combinator::LaterSibling;
                    break;
                }
                Some(_) => {
                    p.pos = before;
                    if any_ws {
                        comb = Combinator::Descendant;
                        break;
                    } else {
                        return Ok(Selector { compounds, combinators });
                    }
                }
            }
        }
        combinators.push(comb);
    }
}

enum QName {
    None,
    // (namespace kind, local name)
    Some(QPrefix, Option<String>),
}

#[derive(Clone, Copy, PartialEq)]
enum QPrefix {
    ImplicitAny,
    ImplicitNoNamespace,
    ExplicitNoNamespace,
    ExplicitAny,
}

/// Returns Err(true) for EndOfInput, Err(false) for other errors.
fn parse_qualified_name(p: &mut P, in_attr: bool) -> Result<QName, bool> {
    let start = p.pos;
    let explicit_ns = |p: &mut P, prefix: QPrefix| -> Result<QName, bool> {
        match p.next_including_whitespace() {
            Some(Tok::Delim('*')) if !in_attr => Ok(QName::Some(prefix, None)),
            Some(Tok::Ident(l)) => Ok(QName::Some(prefix, Some(l.clone()))),
            Some(_) => Err(false),
            None => Err(true),
        }
    };
    match p.next_including_whitespace() {
        Some(Tok::Ident(value)) => {
            let after = p.pos;
            match p.next_including_whitespace() {
                Some(Tok::Delim('|')) => {
                    // No namespace prefixes are declared.
                    Err(false)
                }
                _ => {
                    p.pos = after;
                    if in_attr {
                        Ok(QName::Some(QPrefix::ImplicitNoNamespace, Some(value.clone())))
                    } else {
                        Ok(QName::Some(QPrefix::ImplicitAny, Some(value.clone())))
                    }
                }
            }
        }
        Some(Tok::Delim('*')) => {
            let after = p.pos;
            match p.next_including_whitespace() {
                Some(Tok::Delim('|')) => explicit_ns(p, QPrefix::ExplicitAny),
                r => {
                    p.pos = after;
                    if in_attr {
                        match r {
                            Some(_) => Err(false),
                            None => Err(true),
                        }
                    } else {
                        Ok(QName::Some(QPrefix::ImplicitAny, None))
                    }
                }
            }
        }
        Some(Tok::Delim('|')) => explicit_ns(p, QPrefix::ExplicitNoNamespace),
        Some(_) => {
            p.pos = start;
            Ok(QName::None)
        }
        None => {
            p.pos = start;
            Err(true)
        }
    }
}

/// Returns Ok(true) if a type selector was parsed.
fn parse_type_selector(p: &mut P, sink: &mut Vec<Simple>) -> Result<bool, bool> {
    match parse_qualified_name(p, false) {
        Err(true) => Ok(false),
        Ok(QName::None) => Ok(false),
        Ok(QName::Some(prefix, local)) => {
            match prefix {
                QPrefix::ExplicitNoNamespace => sink.push(Simple::ExplicitNoNamespace),
                _ => {}
            }
            match local {
                Some(name) => {
                    let lower = name.to_ascii_lowercase();
                    sink.push(Simple::LocalName { name, lower });
                }
                None => sink.push(Simple::ExplicitUniversal),
            }
            Ok(true)
        }
        Err(false) => Err(false),
    }
}

enum SimpleResult {
    Simple(Simple),
    PseudoElement,
}

fn parse_compound(p: &mut P) -> PResult<Option<Vec<Simple>>> {
    p.skip_whitespace();
    let mut out = Vec::new();
    let mut empty = true;
    match parse_type_selector(p, &mut out) {
        Ok(true) => empty = false,
        Ok(false) => {}
        Err(_) => return Err(()),
    }
    loop {
        match parse_one_simple(p, false)? {
            None => break,
            Some(SimpleResult::Simple(s)) => {
                out.push(s);
                empty = false;
            }
            Some(SimpleResult::PseudoElement) => {
                // No pseudo-elements are supported.
                return Err(());
            }
        }
    }
    if empty {
        Ok(None)
    } else {
        Ok(Some(out))
    }
}

fn parse_one_simple(p: &mut P, inside_negation: bool) -> PResult<Option<SimpleResult>> {
    let start = p.pos;
    match p.next_including_whitespace() {
        Some(Tok::IDHash(id)) => Ok(Some(SimpleResult::Simple(Simple::Id(id.clone())))),
        Some(Tok::Delim('.')) => match p.next_including_whitespace() {
            Some(Tok::Ident(c)) => Ok(Some(SimpleResult::Simple(Simple::Class(c.clone())))),
            _ => Err(()),
        },
        Some(Tok::SquareBlock(inner)) => {
            let mut np = P::new(inner);
            let s = parse_attribute_selector(&mut np)?;
            if !np.is_exhausted() {
                return Err(());
            }
            Ok(Some(SimpleResult::Simple(s)))
        }
        Some(Tok::Colon) => {
            let (single, next) = match p.next_including_whitespace() {
                Some(Tok::Colon) => (false, p.next_including_whitespace()),
                t => (true, t),
            };
            let (name, args) = match next {
                Some(Tok::Ident(n)) => (n.clone(), None),
                Some(Tok::Function(n, inner)) => (n.clone(), Some(inner)),
                _ => return Err(()),
            };
            let lname = name.to_ascii_lowercase();
            let is_pseudo_element = !single
                || matches!(lname.as_str(), "before" | "after" | "first-line" | "first-letter");
            if is_pseudo_element {
                // kuchiki supports no pseudo-elements
                return Err(());
            }
            match args {
                Some(inner) => {
                    let mut np = P::new(inner);
                    let s = parse_functional_pseudo_class(&mut np, &lname, inside_negation)?;
                    if !np.is_exhausted() {
                        return Err(());
                    }
                    Ok(Some(SimpleResult::Simple(s)))
                }
                None => {
                    let s = match lname.as_str() {
                        "first-child" => Simple::FirstChild,
                        "last-child" => Simple::LastChild,
                        "only-child" => Simple::OnlyChild,
                        "root" => Simple::Root,
                        "empty" => Simple::Empty,
                        "scope" => Simple::Scope,
                        "first-of-type" => Simple::FirstOfType,
                        "last-of-type" => Simple::LastOfType,
                        "only-of-type" => Simple::OnlyOfType,
                        "any-link" => Simple::NonTS(PseudoClass::AnyLink),
                        "link" => Simple::NonTS(PseudoClass::Link),
                        "visited" => Simple::NonTS(PseudoClass::Visited),
                        "active" => Simple::NonTS(PseudoClass::Active),
                        "focus" => Simple::NonTS(PseudoClass::Focus),
                        "hover" => Simple::NonTS(PseudoClass::Hover),
                        "enabled" => Simple::NonTS(PseudoClass::Enabled),
                        "disabled" => Simple::NonTS(PseudoClass::Disabled),
                        "checked" => Simple::NonTS(PseudoClass::Checked),
                        "indeterminate" => Simple::NonTS(PseudoClass::Indeterminate),
                        _ => return Err(()),
                    };
                    Ok(Some(SimpleResult::Simple(s)))
                }
            }
        }
        _ => {
            p.pos = start;
            Ok(None)
        }
    }
}

fn parse_functional_pseudo_class(p: &mut P, name: &str, inside_negation: bool) -> PResult<Simple> {
    match name {
        "nth-child" => {
            let (a, b) = parse_nth(p)?;
            Ok(Simple::Nth { a, b, of_type: false, from_end: false })
        }
        "nth-of-type" => {
            let (a, b) = parse_nth(p)?;
            Ok(Simple::Nth { a, b, of_type: true, from_end: false })
        }
        "nth-last-child" => {
            let (a, b) = parse_nth(p)?;
            Ok(Simple::Nth { a, b, of_type: false, from_end: true })
        }
        "nth-last-of-type" => {
            let (a, b) = parse_nth(p)?;
            Ok(Simple::Nth { a, b, of_type: true, from_end: true })
        }
        "not" => {
            if inside_negation {
                return Err(());
            }
            parse_negation(p)
        }
        _ => Err(()),
    }
}

fn parse_negation(p: &mut P) -> PResult<Simple> {
    let mut seq = Vec::new();
    p.skip_whitespace();
    let is_type = match parse_type_selector(p, &mut seq) {
        Ok(r) => r,
        Err(_) => return Err(()),
    };
    if !is_type {
        // EndOfInput check: parse_type_selector returns Ok(false) at EOF too;
        match parse_one_simple(p, true)? {
            Some(SimpleResult::Simple(s)) => seq.push(s),
            None => return Err(()),
            Some(SimpleResult::PseudoElement) => return Err(()),
        }
    }
    Ok(Simple::Negation(seq))
}

fn parse_n_dash_digits(s: &str) -> Option<i32> {
    let b = s.as_bytes();
    if b.len() >= 3 && b[..2].eq_ignore_ascii_case(b"n-") && b[2..].iter().all(|c| c.is_ascii_digit()) {
        Some(parse_number_saturate(&s[1..]))
    } else {
        None
    }
}

fn parse_number_saturate(s: &str) -> i32 {
    // s is like "-123"
    let v: f64 = s.parse().unwrap_or(0.0);
    if v >= i32::MAX as f64 {
        i32::MAX
    } else if v <= i32::MIN as f64 {
        i32::MIN
    } else {
        v as i32
    }
}

fn parse_b(p: &mut P, a: i32) -> PResult<(i32, i32)> {
    let start = p.pos;
    match p.next() {
        Some(Tok::Delim('+')) => parse_signless_b(p, a, 1),
        Some(Tok::Delim('-')) => parse_signless_b(p, a, -1),
        Some(Tok::Number { has_sign: true, int_value: Some(b) }) => Ok((a, *b)),
        _ => {
            p.pos = start;
            Ok((a, 0))
        }
    }
}

fn parse_signless_b(p: &mut P, a: i32, sign: i32) -> PResult<(i32, i32)> {
    match p.next() {
        Some(Tok::Number { has_sign: false, int_value: Some(b) }) => Ok((a, sign.wrapping_mul(*b))),
        _ => Err(()),
    }
}

fn parse_nth(p: &mut P) -> PResult<(i32, i32)> {
    match p.next() {
        Some(Tok::Number { int_value: Some(b), .. }) => Ok((0, *b)),
        Some(Tok::Dimension { int_value: Some(a), unit, .. }) => {
            let lu = unit.to_ascii_lowercase();
            if lu == "n" {
                parse_b(p, *a)
            } else if lu == "n-" {
                parse_signless_b(p, *a, -1)
            } else {
                match parse_n_dash_digits(unit) {
                    Some(b) => Ok((*a, b)),
                    None => Err(()),
                }
            }
        }
        Some(Tok::Ident(value)) => {
            let lv = value.to_ascii_lowercase();
            match lv.as_str() {
                "even" => Ok((2, 0)),
                "odd" => Ok((2, 1)),
                "n" => parse_b(p, 1),
                "-n" => parse_b(p, -1),
                "n-" => parse_signless_b(p, 1, -1),
                "-n-" => parse_signless_b(p, -1, -1),
                _ => {
                    let (slice, a) = if let Some(rest) = value.strip_prefix('-') { (rest, -1) } else { (value.as_str(), 1) };
                    match parse_n_dash_digits(slice) {
                        Some(b) => Ok((a, b)),
                        None => Err(()),
                    }
                }
            }
        }
        Some(Tok::Delim('+')) => match p.next_including_whitespace() {
            Some(Tok::Ident(value)) => {
                let lv = value.to_ascii_lowercase();
                match lv.as_str() {
                    "n" => parse_b(p, 1),
                    "n-" => parse_signless_b(p, 1, -1),
                    _ => match parse_n_dash_digits(value) {
                        Some(b) => Ok((1, b)),
                        None => Err(()),
                    },
                }
            }
            _ => Err(()),
        },
        _ => Err(()),
    }
}

fn parse_attribute_selector(p: &mut P) -> PResult<Simple> {
    p.skip_whitespace();
    let (ns, local) = match parse_qualified_name(p, true) {
        Ok(QName::None) => return Err(()),
        Ok(QName::Some(_, None)) => return Err(()),
        Ok(QName::Some(prefix, Some(l))) => {
            let ns = match prefix {
                QPrefix::ExplicitAny => Some(NsConstraint::Any),
                _ => None,
            };
            (ns, l)
        }
        Err(_) => return Err(()),
    };
    let lower = local.to_ascii_lowercase();
    let op = match p.next() {
        None => {
            return Ok(Simple::AttrExists { ns: ns.unwrap_or(NsConstraint::Empty), local, lower });
        }
        Some(Tok::Delim('=')) => AttrOp::Equal,
        Some(Tok::IncludeMatch) => AttrOp::Includes,
        Some(Tok::DashMatch) => AttrOp::DashMatch,
        Some(Tok::PrefixMatch) => AttrOp::Prefix,
        Some(Tok::SubstringMatch) => AttrOp::Substring,
        Some(Tok::SuffixMatch) => AttrOp::Suffix,
        Some(_) => return Err(()),
    };
    let value = match p.next() {
        Some(Tok::Ident(v)) | Some(Tok::QuotedString(v)) => v.clone(),
        _ => return Err(()),
    };
    let never = match op {
        AttrOp::Equal | AttrOp::DashMatch => false,
        AttrOp::Includes => value.is_empty() || value.contains([' ', '\t', '\n', '\r', '\x0c']),
        AttrOp::Prefix | AttrOp::Substring | AttrOp::Suffix => value.is_empty(),
    };
    // flags
    let case = match p.next() {
        None => {
            if ns.is_none() && CASE_INSENSITIVE_HTML_ATTRS.contains(&lower.as_str()) {
                CaseSens::InsensitiveIfHtml
            } else {
                CaseSens::Sensitive
            }
        }
        Some(Tok::Ident(f)) => {
            if f.eq_ignore_ascii_case("i") {
                CaseSens::Insensitive
            } else if f.eq_ignore_ascii_case("s") {
                CaseSens::ExplicitSensitive
            } else {
                return Err(());
            }
        }
        Some(_) => return Err(()),
    };
    Ok(Simple::AttrValue { ns: ns.unwrap_or(NsConstraint::Empty), local, lower, op, value, case, never })
}

// ---------------- matching ----------------

fn is_html_elem(e: &ElementData) -> bool {
    e.ns == NS_HTML
}

fn element_parent(dom: &Dom, n: NodeId) -> Option<NodeId> {
    let p = dom.parent(n)?;
    if dom.is_element(p) {
        Some(p)
    } else {
        None
    }
}

fn prev_element(dom: &Dom, n: NodeId) -> Option<NodeId> {
    let mut c = dom.prev_sibling(n);
    while let Some(x) = c {
        if dom.is_element(x) {
            return Some(x);
        }
        c = dom.prev_sibling(x);
    }
    None
}

fn next_element(dom: &Dom, n: NodeId) -> Option<NodeId> {
    let mut c = dom.next_sibling(n);
    while let Some(x) = c {
        if dom.is_element(x) {
            return Some(x);
        }
        c = dom.next_sibling(x);
    }
    None
}

fn is_root(dom: &Dom, n: NodeId) -> bool {
    match dom.parent(n) {
        Some(p) => matches!(dom.node(p).data, NodeData::Document),
        None => false,
    }
}

fn case_eq(a: &[u8], b: &[u8], insensitive: bool) -> bool {
    if insensitive {
        a.eq_ignore_ascii_case(b)
    } else {
        a == b
    }
}

fn case_contains(hay: &str, needle: &str, insensitive: bool) -> bool {
    if !insensitive {
        return hay.contains(needle);
    }
    let h = hay.as_bytes();
    let n = needle.as_bytes();
    if n.is_empty() {
        return true;
    }
    for i in 0..h.len() {
        if !h[i].eq_ignore_ascii_case(&n[0]) {
            continue;
        }
        let after = &h[i + 1..];
        if after.len() >= n.len() - 1 && after[..n.len() - 1].eq_ignore_ascii_case(&n[1..]) {
            return true;
        }
    }
    false
}

fn eval_op(op: AttrOp, e: &str, s: &str, insensitive: bool) -> bool {
    let eb = e.as_bytes();
    let sb = s.as_bytes();
    match op {
        AttrOp::Equal => case_eq(eb, sb, insensitive),
        AttrOp::Prefix => eb.len() >= sb.len() && case_eq(&eb[..sb.len()], sb, insensitive),
        AttrOp::Suffix => eb.len() >= sb.len() && case_eq(&eb[eb.len() - sb.len()..], sb, insensitive),
        AttrOp::Substring => case_contains(e, s, insensitive),
        AttrOp::Includes => e
            .split([' ', '\t', '\n', '\r', '\x0c'])
            .any(|part| case_eq(part.as_bytes(), sb, insensitive)),
        AttrOp::DashMatch => {
            case_eq(eb, sb, insensitive) || (eb.get(sb.len()) == Some(&b'-') && case_eq(&eb[..sb.len()], sb, insensitive))
        }
    }
}

fn attr_matches<F: Fn(&str) -> bool>(e: &ElementData, ns: &NsConstraint, local: &str, f: F) -> bool {
    match ns {
        NsConstraint::Any => e.attrs.iter().any(|a| a.local == local && f(&a.value)),
        NsConstraint::Empty => e.attrs.iter().any(|a| a.ns.is_empty() && a.local == local && f(&a.value)),
    }
}

fn nth_index(dom: &Dom, n: NodeId, of_type: bool, from_end: bool) -> i32 {
    let e = dom.element(n).unwrap();
    let mut idx: i32 = 1;
    let mut cur = n;
    loop {
        let nx = if from_end { next_element(dom, cur) } else { prev_element(dom, cur) };
        match nx {
            None => break,
            Some(x) => {
                cur = x;
                if !of_type || {
                    let o = dom.element(x).unwrap();
                    o.ns == e.ns && o.local == e.local
                } {
                    idx = idx.wrapping_add(1);
                }
            }
        }
    }
    idx
}

fn matches_simple(dom: &Dom, n: NodeId, s: &Simple) -> bool {
    let e = dom.element(n).unwrap();
    match s {
        Simple::LocalName { name, lower } => {
            let nm = if is_html_elem(e) { lower } else { name };
            e.local == *nm
        }
        Simple::ExplicitUniversal => true,
        Simple::ExplicitNoNamespace => e.ns.is_empty(),
        Simple::Id(id) => e.get_attr("id").map_or(false, |v| v == id),
        Simple::Class(c) => {
            !c.is_empty()
                && e.get_attr("class").map_or(false, |v| v.split([' ', '\t', '\n', '\r', '\x0c']).any(|x| x == c))
        }
        Simple::AttrExists { ns, local, lower } => {
            let nm = if is_html_elem(e) { lower } else { local };
            attr_matches(e, ns, nm, |_| true)
        }
        Simple::AttrValue { ns, local, lower, op, value, case, never } => {
            if *never {
                return false;
            }
            let html = is_html_elem(e);
            let nm = if html { lower } else { local };
            let insensitive = match case {
                CaseSens::ExplicitSensitive | CaseSens::Sensitive => false,
                CaseSens::Insensitive => true,
                CaseSens::InsensitiveIfHtml => html,
            };
            attr_matches(e, ns, nm, |v| eval_op(*op, v, value, insensitive))
        }
        Simple::Negation(seq) => !seq.iter().all(|x| matches_simple(dom, n, x)),
        Simple::FirstChild => prev_element(dom, n).is_none(),
        Simple::LastChild => next_element(dom, n).is_none(),
        Simple::OnlyChild => prev_element(dom, n).is_none() && next_element(dom, n).is_none(),
        Simple::Root => is_root(dom, n),
        Simple::Scope => is_root(dom, n),
        Simple::Empty => dom.children(n).iter().all(|&c| match &dom.node(c).data {
            NodeData::Element(_) => false,
            NodeData::Text(t) => t.is_empty(),
            _ => true,
        }),
        Simple::Nth { a, b, of_type, from_end } => {
            let idx = nth_index(dom, n, *of_type, *from_end);
            match idx.checked_sub(*b) {
                None => false,
                Some(an) => match an.checked_div(*a) {
                    Some(k) => k >= 0 && a.wrapping_mul(k) == an,
                    None => an == 0,
                },
            }
        }
        Simple::FirstOfType => nth_index(dom, n, true, false) == 1,
        Simple::LastOfType => nth_index(dom, n, true, true) == 1,
        Simple::OnlyOfType => nth_index(dom, n, true, false) == 1 && nth_index(dom, n, true, true) == 1,
        Simple::NonTS(pc) => match pc {
            PseudoClass::AnyLink | PseudoClass::Link => {
                e.ns == NS_HTML && matches!(e.local.as_str(), "a" | "area" | "link") && e.has_attr("href")
            }
            _ => false,
        },
    }
}

fn matches_compound(dom: &Dom, n: NodeId, c: &[Simple]) -> bool {
    c.iter().all(|s| matches_simple(dom, n, s))
}

fn matches_from(dom: &Dom, n: NodeId, sel: &Selector, idx: usize) -> bool {
    if !matches_compound(dom, n, &sel.compounds[idx]) {
        return false;
    }
    if idx == 0 {
        return true;
    }
    let comb = sel.combinators[idx - 1];
    match comb {
        Combinator::Child => match element_parent(dom, n) {
            Some(p) => matches_from(dom, p, sel, idx - 1),
            None => false,
        },
        Combinator::Descendant => {
            let mut cur = element_parent(dom, n);
            while let Some(p) = cur {
                if matches_from(dom, p, sel, idx - 1) {
                    return true;
                }
                cur = element_parent(dom, p);
            }
            false
        }
        Combinator::NextSibling => match prev_element(dom, n) {
            Some(p) => matches_from(dom, p, sel, idx - 1),
            None => false,
        },
        Combinator::LaterSibling => {
            let mut cur = prev_element(dom, n);
            while let Some(p) = cur {
                if matches_from(dom, p, sel, idx - 1) {
                    return true;
                }
                cur = prev_element(dom, p);
            }
            false
        }
    }
}

impl SelectorList {
    pub fn matches(&self, dom: &Dom, n: NodeId) -> bool {
        if !dom.is_element(n) {
            return false;
        }
        self.0.iter().any(|s| matches_from(dom, n, s, s.compounds.len() - 1))
    }
}
