//! Command-line parsing emulating clap 2.x behaviour for htmlq's argument set.

use std::io::IsTerminal;

#[derive(Default, Debug)]
pub struct Config {
    pub attribute: Option<String>,
    pub base: Option<String>,
    pub detect_base: bool,
    pub filename: Option<String>,
    pub output: Option<String>,
    pub ignore_whitespace: bool,
    pub pretty: bool,
    pub text: bool,
    pub remove_nodes: Vec<String>,
    pub selectors: Vec<String>,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ArgId {
    DetectBase,
    IgnoreWhitespace,
    Pretty,
    Text,
    Help,
    Version,
    Attribute,
    Base,
    Filename,
    Output,
    RemoveNodes,
}

struct ArgDef {
    id: ArgId,
    short: char,
    long: &'static str,
    value: Option<&'static str>,
    multiple: bool,
}

const ARGS: &[ArgDef] = &[
    ArgDef { id: ArgId::DetectBase, short: 'B', long: "detect-base", value: None, multiple: false },
    ArgDef { id: ArgId::IgnoreWhitespace, short: 'w', long: "ignore-whitespace", value: None, multiple: false },
    ArgDef { id: ArgId::Pretty, short: 'p', long: "pretty", value: None, multiple: false },
    ArgDef { id: ArgId::Text, short: 't', long: "text", value: None, multiple: false },
    ArgDef { id: ArgId::Help, short: 'h', long: "help", value: None, multiple: false },
    ArgDef { id: ArgId::Version, short: 'V', long: "version", value: None, multiple: false },
    ArgDef { id: ArgId::Attribute, short: 'a', long: "attribute", value: Some("attribute"), multiple: false },
    ArgDef { id: ArgId::Base, short: 'b', long: "base", value: Some("base"), multiple: false },
    ArgDef { id: ArgId::Filename, short: 'f', long: "filename", value: Some("FILE"), multiple: false },
    ArgDef { id: ArgId::Output, short: 'o', long: "output", value: Some("FILE"), multiple: false },
    ArgDef { id: ArgId::RemoveNodes, short: 'r', long: "remove-nodes", value: Some("SELECTOR"), multiple: true },
];

// Order used for "did you mean" suggestions: flags (incl. help/version), then options.
const SUGGEST_ORDER: &[ArgId] = &[
    ArgId::Text,
    ArgId::IgnoreWhitespace,
    ArgId::Pretty,
    ArgId::DetectBase,
    ArgId::Help,
    ArgId::Version,
    ArgId::Attribute,
    ArgId::Base,
    ArgId::Filename,
    ArgId::Output,
    ArgId::RemoveNodes,
];

fn def(id: ArgId) -> &'static ArgDef {
    ARGS.iter().find(|a| a.id == id).unwrap()
}

fn arg_display(id: ArgId) -> String {
    let d = def(id);
    match d.value {
        None => format!("--{}", d.long),
        Some(v) => {
            if d.multiple {
                format!("--{} <{}>...", d.long, v)
            } else {
                format!("--{} <{}>", d.long, v)
            }
        }
    }
}

struct Matched {
    id: ArgId,
    occurs: u32,
    vals: Vec<String>,
}

struct Matcher {
    args: Vec<Matched>,
}

impl Matcher {
    fn get_mut(&mut self, id: ArgId) -> &mut Matched {
        if let Some(i) = self.args.iter().position(|m| m.id == id) {
            &mut self.args[i]
        } else {
            self.args.push(Matched { id, occurs: 0, vals: Vec::new() });
            self.args.last_mut().unwrap()
        }
    }
    fn get(&self, id: ArgId) -> Option<&Matched> {
        self.args.iter().find(|m| m.id == id)
    }
}

pub const HELP_TEMPLATE: &str = "htmlq 0.4.0
Michael Maclean <michael@mgdm.net>
Runs CSS selectors on HTML

USAGE:
    {bin} [FLAGS] [OPTIONS] [--] [selector]...

FLAGS:
    -B, --detect-base          Try to detect the base URL from the <base> tag in the document. If not found, default to
                               the value of --base, if supplied
    -h, --help                 Prints help information
    -w, --ignore-whitespace    When printing text nodes, ignore those that consist entirely of whitespace
    -p, --pretty               Pretty-print the serialised output
    -t, --text                 Output only the contents of text nodes inside selected elements
    -V, --version              Prints version information

OPTIONS:
    -a, --attribute <attribute>         Only return this attribute (if present) from selected elements
    -b, --base <base>                   Use this URL as the base for links
    -f, --filename <FILE>               The input file. Defaults to stdin
    -o, --output <FILE>                 The output file. Defaults to stdout
    -r, --remove-nodes <SELECTOR>...    Remove nodes matching this expression before output. May be specified multiple
                                        times

ARGS:
    <selector>...    The CSS expression to select [default: html]
";

pub enum CliResult {
    Run(Config),
    Exit(i32),
}

struct Colors {
    on: bool,
}

impl Colors {
    fn error(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[1;31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn warning(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn good(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

fn jaro(a: &str, b: &str) -> f64 {
    if a == b {
        return 1.0;
    }
    let a_len = a.chars().count();
    let b_len = b.chars().count();
    if a_len == 0 || b_len == 0 || (a_len == 1 && b_len == 1) {
        return 0.0;
    }
    let search_range = (std::cmp::max(a_len, b_len) / 2).saturating_sub(1);
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    let bchars: Vec<char> = b.chars().collect();
    for (i, a_char) in a.chars().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = std::cmp::min(b_len - 1, i + search_range);
        for j in 0..=max_bound {
            if j >= bchars.len() {
                break;
            }
            let b_char = bchars[j];
            if min_bound <= j && a_char == b_char && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0) * ((matches / a_len as f64) + (matches / b_len as f64) + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jd = jaro(a, b);
    let prefix = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count();
    let jw = jd + (0.1 * prefix as f64 * (1.0 - jd));
    if jw <= 1.0 {
        jw
    } else {
        1.0
    }
}

fn did_you_mean(arg: &str) -> Option<ArgId> {
    let mut cand: Option<(f64, ArgId)> = None;
    for &id in SUGGEST_ORDER {
        let conf = jaro_winkler(arg, def(id).long);
        if conf > 0.8 && (cand.is_none() || cand.unwrap().0 < conf) {
            cand = Some((conf, id));
        }
    }
    cand.map(|c| c.1)
}

fn usage(bin: &str, matcher: &Matcher, extra: Option<ArgId>) -> String {
    let mut used: Vec<ArgId> = matcher.args.iter().map(|m| m.id).collect();
    if let Some(e) = extra {
        used.push(e);
    }
    if used.is_empty() {
        return format!("USAGE:\n    {} [FLAGS] [OPTIONS] [--] [selector]...", bin);
    }
    let mut names: Vec<&'static str> = used.iter().map(|&id| def(id).long).collect();
    names.sort();
    names.dedup();
    let mut s = format!("USAGE:\n    {}", bin);
    for n in names {
        let id = ARGS.iter().find(|a| a.long == n).unwrap().id;
        s.push(' ');
        s.push_str(&arg_display(id));
    }
    s
}

enum ParseRes {
    Flag,
    Opt(ArgId),
    ValuesDone,
}

enum Fail {
    Help,
    Version,
    Error(String),
}

pub fn parse(args: Vec<String>) -> CliResult {
    let bin = args
        .first()
        .map(|a| {
            std::path::Path::new(a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| "htmlq".to_string());
    let colors = Colors {
        on: std::io::stderr().is_terminal() && std::env::var("TERM").ok().as_deref() != Some("dumb"),
    };
    match parse_inner(&bin, &args[1.min(args.len())..], &colors) {
        Ok(cfg) => CliResult::Run(cfg),
        Err(Fail::Help) => {
            use std::io::Write;
            let s = HELP_TEMPLATE.replace("{bin}", &bin);
            let mut out = std::io::stdout();
            let _ = out.write_all(s.as_bytes());
            let _ = out.flush();
            CliResult::Exit(0)
        }
        Err(Fail::Version) => {
            use std::io::Write;
            let mut out = std::io::stdout();
            let _ = out.write_all(b"htmlq 0.4.0\n");
            let _ = out.flush();
            CliResult::Exit(0)
        }
        Err(Fail::Error(msg)) => {
            use std::io::Write;
            let mut e = std::io::stderr();
            let _ = e.write_all(msg.as_bytes());
            let _ = e.write_all(b"\n");
            let _ = e.flush();
            CliResult::Exit(1)
        }
    }
}

fn err_unknown(bin: &str, c: &Colors, arg: &str, suffix: &str, matcher: &Matcher, extra: Option<ArgId>) -> Fail {
    Fail::Error(format!(
        "{} Found argument '{}' which wasn't expected, or isn't valid in this context{}\n\n{}\n\nFor more information try {}",
        c.error("error:"),
        c.warning(arg),
        suffix,
        usage(bin, matcher, extra),
        c.good("--help")
    ))
}

fn err_empty(bin: &str, c: &Colors, id: ArgId, matcher: &Matcher) -> Fail {
    Fail::Error(format!(
        "{} The argument '{}' requires a value but none was supplied\n\n{}\n\nFor more information try {}",
        c.error("error:"),
        c.warning(&arg_display(id)),
        usage(bin, matcher, None),
        c.good("--help")
    ))
}

fn err_multiple(bin: &str, c: &Colors, id: ArgId, matcher: &Matcher) -> Fail {
    Fail::Error(format!(
        "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try {}",
        c.error("error:"),
        c.warning(&arg_display(id)),
        usage(bin, matcher, None),
        c.good("--help")
    ))
}

fn parse_opt(matcher: &mut Matcher, id: ArgId, val: Option<&str>) -> ParseRes {
    let d = def(id);
    let m = matcher.get_mut(id);
    let mut no_val = true;
    if let Some(v) = val {
        let v = v.trim_start_matches('=');
        m.vals.push(v.to_string());
        no_val = false;
    }
    m.occurs += 1;
    if no_val {
        return ParseRes::Opt(id);
    }
    let _ = d;
    ParseRes::ValuesDone
}

fn parse_inner(bin: &str, args: &[String], c: &Colors) -> Result<Config, Fail> {
    let mut matcher = Matcher { args: Vec::new() };
    let mut positionals: Vec<String> = Vec::new();
    let mut needs_val_of: Option<ArgId> = None;
    let mut trailing = false;
    let mut last_res = ParseRes::ValuesDone;
    let _ = &last_res;

    for arg in args {
        if !trailing {
            let starts_new_arg = arg.starts_with('-') && arg.len() != 1;
            if arg == "--" {
                trailing = true;
                continue;
            }
            if starts_new_arg {
                if arg.starts_with("--") {
                    let full = arg.trim_start_matches('-');
                    let (name, val) = match full.find('=') {
                        Some(i) => (&full[..i], Some(&full[i + 1..])),
                        None => (full, None),
                    };
                    if let Some(d) = ARGS.iter().find(|a| a.long == name && a.value.is_some()) {
                        let r = parse_opt(&mut matcher, d.id, val);
                        needs_val_of = match r {
                            ParseRes::Opt(id) => Some(id),
                            _ => None,
                        };
                        last_res = r;
                        continue;
                    } else if let Some(d) = ARGS.iter().find(|a| a.long == name && a.value.is_none()) {
                        if d.id == ArgId::Help {
                            return Err(Fail::Help);
                        }
                        if d.id == ArgId::Version {
                            return Err(Fail::Version);
                        }
                        matcher.get_mut(d.id).occurs += 1;
                        needs_val_of = None;
                        last_res = ParseRes::Flag;
                        continue;
                    } else {
                        let sugg = did_you_mean(name);
                        let suffix = match sugg {
                            Some(id) => format!(
                                "\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{}\x1b[0m?",
                                def(id).long
                            ),
                            None => String::new(),
                        };
                        let used = format!("--{}", name);
                        return Err(err_unknown(bin, c, &used, &suffix, &matcher, sugg));
                    }
                } else {
                    let s = arg.trim_start_matches('-');
                    let mut res = ParseRes::Flag;
                    let mut handled_opt = false;
                    for (ci, ch) in s.char_indices() {
                        if let Some(d) = ARGS.iter().find(|a| a.short == ch && a.value.is_some()) {
                            let rest = &s[ci + ch.len_utf8()..];
                            let val = if rest.is_empty() { None } else { Some(rest) };
                            let r = parse_opt(&mut matcher, d.id, val);
                            needs_val_of = match r {
                                ParseRes::Opt(id) => Some(id),
                                _ => None,
                            };
                            last_res = r;
                            handled_opt = true;
                            break;
                        } else if let Some(d) = ARGS.iter().find(|a| a.short == ch && a.value.is_none()) {
                            if d.id == ArgId::Help {
                                return Err(Fail::Help);
                            }
                            if d.id == ArgId::Version {
                                return Err(Fail::Version);
                            }
                            matcher.get_mut(d.id).occurs += 1;
                            res = ParseRes::Flag;
                        } else {
                            let a = format!("-{}", ch);
                            return Err(err_unknown(bin, c, &a, "", &matcher, None));
                        }
                    }
                    if !handled_opt {
                        needs_val_of = None;
                        last_res = res;
                    }
                    continue;
                }
            } else if let Some(id) = needs_val_of {
                let m = matcher.get_mut(id);
                m.vals.push(arg.clone());
                // After one value, both single-valued and number_of_values(1) options are done.
                needs_val_of = None;
                last_res = ParseRes::ValuesDone;
                continue;
            }
        }
        positionals.push(arg.clone());
    }

    // Validation
    if let Some(id) = needs_val_of {
        let empty = matcher.get(id).map(|m| m.vals.is_empty()).unwrap_or(true);
        if empty {
            return Err(err_empty(bin, c, id, &matcher));
        }
    }
    for m in &matcher.args {
        let d = def(m.id);
        if d.value.is_some() && m.vals.is_empty() {
            return Err(err_empty(bin, c, m.id, &matcher));
        }
        if m.occurs > 1 && !d.multiple {
            return Err(err_multiple(bin, c, m.id, &matcher));
        }
    }

    let mut cfg = Config::default();
    for m in &matcher.args {
        match m.id {
            ArgId::DetectBase => cfg.detect_base = true,
            ArgId::IgnoreWhitespace => cfg.ignore_whitespace = true,
            ArgId::Pretty => cfg.pretty = true,
            ArgId::Text => cfg.text = true,
            ArgId::Attribute => cfg.attribute = m.vals.first().cloned(),
            ArgId::Base => cfg.base = m.vals.first().cloned(),
            ArgId::Filename => cfg.filename = m.vals.first().cloned(),
            ArgId::Output => cfg.output = m.vals.first().cloned(),
            ArgId::RemoveNodes => cfg.remove_nodes = m.vals.clone(),
            _ => {}
        }
    }
    if positionals.is_empty() {
        positionals.push("html".to_string());
    }
    cfg.selectors = positionals;
    Ok(cfg)
}
