//! A WHATWG URL parser, sufficient for parsing and joining URLs.

#[derive(Clone, Debug, PartialEq)]
enum Host {
    Domain(String),
    Opaque(String),
    Ipv4(u32),
    Ipv6([u16; 8]),
    Empty,
}

#[derive(Clone, Debug)]
pub struct Url {
    scheme: String,
    username: String,
    password: String,
    host: Option<Host>,
    port: Option<u16>,
    path: Vec<String>,
    opaque_path: Option<String>,
    query: Option<String>,
    fragment: Option<String>,
}

fn is_special(s: &str) -> bool {
    matches!(s, "ftp" | "file" | "http" | "https" | "ws" | "wss")
}

fn default_port(s: &str) -> Option<u16> {
    match s {
        "ftp" => Some(21),
        "http" | "ws" => Some(80),
        "https" | "wss" => Some(443),
        _ => None,
    }
}

fn in_c0_set(c: char) -> bool {
    (c as u32) < 0x20 || (c as u32) > 0x7E
}
fn in_fragment_set(c: char) -> bool {
    in_c0_set(c) || matches!(c, ' ' | '"' | '<' | '>' | '`')
}
fn in_query_set(c: char) -> bool {
    in_c0_set(c) || matches!(c, ' ' | '"' | '#' | '<' | '>')
}
fn in_special_query_set(c: char) -> bool {
    in_query_set(c) || c == '\''
}
fn in_path_set(c: char) -> bool {
    in_fragment_set(c) || matches!(c, '#' | '?' | '{' | '}')
}
fn in_userinfo_set(c: char) -> bool {
    in_path_set(c) || matches!(c, '/' | ':' | ';' | '=' | '@' | '[' | '\\' | ']' | '^' | '|')
}

fn pct_encode(out: &mut String, c: char, set: fn(char) -> bool) {
    if set(c) {
        let mut buf = [0u8; 4];
        for b in c.encode_utf8(&mut buf).bytes() {
            out.push_str(&format!("%{:02X}", b));
        }
    } else {
        out.push(c);
    }
}

fn pct_decode(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' && i + 2 < b.len() + 0 && i + 2 <= b.len() - 1 + 0 {
            let h = &b[i + 1..i + 3];
            if h[0].is_ascii_hexdigit() && h[1].is_ascii_hexdigit() {
                let v = u8::from_str_radix(std::str::from_utf8(h).unwrap(), 16).unwrap();
                out.push(v);
                i += 3;
                continue;
            }
        }
        out.push(b[i]);
        i += 1;
    }
    out
}

fn is_windows_drive_letter(s: &[char], normalized: bool) -> bool {
    s.len() == 2 && s[0].is_ascii_alphabetic() && (s[1] == ':' || (!normalized && s[1] == '|'))
}

fn starts_with_windows_drive_letter(s: &[char]) -> bool {
    s.len() >= 2
        && is_windows_drive_letter(&s[..2], false)
        && (s.len() == 2 || matches!(s[2], '/' | '\\' | '?' | '#'))
}

fn is_single_dot(s: &str) -> bool {
    s == "." || s.eq_ignore_ascii_case("%2e")
}

fn is_double_dot(s: &str) -> bool {
    matches!(s.to_ascii_lowercase().as_str(), ".." | ".%2e" | "%2e." | "%2e%2e")
}

// ---------- punycode ----------
fn punycode_encode(input: &[char]) -> Option<String> {
    let base: u32 = 36;
    let tmin = 1;
    let tmax = 26;
    let skew = 38;
    let damp = 700;
    let mut n: u32 = 128;
    let mut delta: u32 = 0;
    let mut bias: u32 = 72;
    let mut output = String::new();
    for &c in input {
        if (c as u32) < 128 {
            output.push(c);
        }
    }
    let b = output.len() as u32;
    let mut h = b;
    if b > 0 {
        output.push('-');
    }
    let adapt = |mut delta: u32, numpoints: u32, first: bool| -> u32 {
        delta = if first { delta / damp } else { delta / 2 };
        delta += delta / numpoints;
        let mut k = 0;
        while delta > ((base - tmin) * tmax) / 2 {
            delta /= base - tmin;
            k += base;
        }
        k + (((base - tmin + 1) * delta) / (delta + skew))
    };
    let digit = |d: u32| -> char {
        if d < 26 {
            (b'a' + d as u8) as char
        } else {
            (b'0' + (d - 26) as u8) as char
        }
    };
    let total = input.len() as u32;
    while h < total {
        let m = input.iter().map(|&c| c as u32).filter(|&c| c >= n).min()?;
        delta = delta.checked_add((m - n).checked_mul(h + 1)?)?;
        n = m;
        for &c in input {
            let c = c as u32;
            if c < n {
                delta = delta.checked_add(1)?;
            }
            if c == n {
                let mut q = delta;
                let mut k = base;
                loop {
                    let t = if k <= bias {
                        tmin
                    } else if k >= bias + tmax {
                        tmax
                    } else {
                        k - bias
                    };
                    if q < t {
                        break;
                    }
                    output.push(digit(t + (q - t) % (base - t)));
                    q = (q - t) / (base - t);
                    k += base;
                }
                output.push(digit(q));
                bias = adapt(delta, h + 1, h == b);
                delta = 0;
                h += 1;
            }
        }
        delta += 1;
        n += 1;
    }
    Some(output)
}

fn domain_to_ascii(domain: &str) -> Option<String> {
    // Simplified UTS46 processing: lowercase and punycode-encode labels.
    let mapped: String = domain
        .chars()
        .flat_map(|c| {
            let v: Vec<char> = match c {
                '\u{3002}' | '\u{FF0E}' | '\u{FF61}' => vec!['.'],
                '\u{00AD}' | '\u{200B}' | '\u{2060}' | '\u{FEFF}' | '\u{200C}' | '\u{200D}' => vec![],
                _ => c.to_lowercase().collect(),
            };
            v.into_iter()
        })
        .collect();
    let mut out = Vec::new();
    for label in mapped.split('.') {
        if label.is_ascii() {
            out.push(label.to_string());
        } else {
            let chars: Vec<char> = label.chars().collect();
            out.push(format!("xn--{}", punycode_encode(&chars)?));
        }
    }
    Some(out.join("."))
}

fn parse_ipv4_number(s: &str) -> Option<u64> {
    if s.is_empty() {
        return None;
    }
    let (digits, radix) = if s.len() >= 2 && (s.starts_with("0x") || s.starts_with("0X")) {
        (&s[2..], 16)
    } else if s.len() >= 2 && s.starts_with('0') {
        (&s[1..], 8)
    } else {
        (s, 10)
    };
    if digits.is_empty() {
        return Some(0);
    }
    let mut v: u64 = 0;
    for c in digits.chars() {
        let d = c.to_digit(radix)? as u64;
        v = v.saturating_mul(radix as u64).saturating_add(d);
        if v > u64::from(u32::MAX) * 256 {
            v = u64::from(u32::MAX) * 256;
        }
    }
    Some(v)
}

fn ends_in_number(s: &str) -> bool {
    let mut parts: Vec<&str> = s.split('.').collect();
    if parts.last() == Some(&"") {
        if parts.len() == 1 {
            return false;
        }
        parts.pop();
    }
    let last = parts.last().unwrap();
    if !last.is_empty() && last.chars().all(|c| c.is_ascii_digit()) {
        return true;
    }
    parse_ipv4_number(last).is_some()
}

fn parse_ipv4(s: &str) -> Option<u32> {
    let mut parts: Vec<&str> = s.split('.').collect();
    if parts.last() == Some(&"") && parts.len() > 1 {
        parts.pop();
    }
    if parts.len() > 4 {
        return None;
    }
    let mut nums = Vec::new();
    for p in &parts {
        nums.push(parse_ipv4_number(p)?);
    }
    for (i, &n) in nums.iter().enumerate() {
        if n > 255 && i != nums.len() - 1 {
            return None;
        }
    }
    let last = *nums.last()?;
    if last >= 256u64.pow((5 - nums.len()) as u32) {
        return None;
    }
    let mut ipv4 = last;
    for (i, &n) in nums.iter().enumerate().take(nums.len() - 1) {
        ipv4 += n * 256u64.pow((3 - i) as u32);
    }
    Some(ipv4 as u32)
}

fn parse_ipv6(input: &str) -> Option<[u16; 8]> {
    let c: Vec<char> = input.chars().collect();
    let mut addr = [0u16; 8];
    let mut piece_index = 0usize;
    let mut compress: Option<usize> = None;
    let mut p = 0usize;
    if c.get(p) == Some(&':') {
        if c.get(p + 1) != Some(&':') {
            return None;
        }
        p += 2;
        piece_index += 1;
        compress = Some(piece_index);
    }
    while p < c.len() {
        if piece_index == 8 {
            return None;
        }
        if c[p] == ':' {
            if compress.is_some() {
                return None;
            }
            p += 1;
            piece_index += 1;
            compress = Some(piece_index);
            continue;
        }
        let mut value: u32 = 0;
        let mut length = 0;
        while length < 4 && p < c.len() && c[p].is_ascii_hexdigit() {
            value = value * 16 + c[p].to_digit(16).unwrap();
            p += 1;
            length += 1;
        }
        if p < c.len() && c[p] == '.' {
            if length == 0 {
                return None;
            }
            p -= length;
            if piece_index > 6 {
                return None;
            }
            let mut numbers_seen = 0;
            while p < c.len() {
                let mut ipv4_piece: Option<u32> = None;
                if numbers_seen > 0 {
                    if c[p] == '.' && numbers_seen < 4 {
                        p += 1;
                    } else {
                        return None;
                    }
                }
                if p >= c.len() || !c[p].is_ascii_digit() {
                    return None;
                }
                while p < c.len() && c[p].is_ascii_digit() {
                    let number = c[p].to_digit(10).unwrap();
                    match ipv4_piece {
                        None => ipv4_piece = Some(number),
                        Some(0) => return None,
                        Some(v) => ipv4_piece = Some(v * 10 + number),
                    }
                    if ipv4_piece.unwrap() > 255 {
                        return None;
                    }
                    p += 1;
                }
                addr[piece_index] = (addr[piece_index] as u32 * 0x100 + ipv4_piece.unwrap()) as u16;
                numbers_seen += 1;
                if numbers_seen == 2 || numbers_seen == 4 {
                    piece_index += 1;
                }
            }
            if numbers_seen != 4 {
                return None;
            }
            break;
        } else if p < c.len() && c[p] == ':' {
            p += 1;
            if p >= c.len() {
                return None;
            }
        } else if p < c.len() {
            return None;
        }
        addr[piece_index] = value as u16;
        piece_index += 1;
    }
    if let Some(comp) = compress {
        let mut swaps = piece_index - comp;
        piece_index = 7;
        while piece_index != 0 && swaps > 0 {
            addr.swap(piece_index, comp + swaps - 1);
            piece_index -= 1;
            swaps -= 1;
        }
    } else if piece_index != 8 {
        return None;
    }
    Some(addr)
}

fn parse_host(input: &str, not_special: bool) -> Option<Host> {
    if input.starts_with('[') {
        if !input.ends_with(']') || input.len() < 2 {
            return None;
        }
        return parse_ipv6(&input[1..input.len() - 1]).map(Host::Ipv6);
    }
    if not_special {
        // opaque host
        for c in input.chars() {
            if matches!(
                c,
                '\0' | '\t' | '\n' | '\r' | ' ' | '#' | '/' | ':' | '<' | '>' | '?' | '@' | '[' | '\\' | ']' | '^' | '|'
            ) {
                return None;
            }
        }
        let mut out = String::new();
        for c in input.chars() {
            pct_encode(&mut out, c, in_c0_set);
        }
        return Some(Host::Opaque(out));
    }
    let decoded = String::from_utf8_lossy(&pct_decode(input)).into_owned();
    let ascii = domain_to_ascii(&decoded)?;
    if ascii.is_empty() {
        return None;
    }
    for c in ascii.chars() {
        if matches!(
            c,
            '\0' | '\t' | '\n' | '\r' | ' ' | '#' | '%' | '/' | ':' | '<' | '>' | '?' | '@' | '[' | '\\' | ']' | '^' | '|'
        ) || (c as u32) < 0x20
            || c == '\u{7f}'
        {
            return None;
        }
    }
    if ends_in_number(&ascii) {
        return parse_ipv4(&ascii).map(Host::Ipv4);
    }
    Some(Host::Domain(ascii))
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum St {
    SchemeStart,
    Scheme,
    NoScheme,
    SpecialRelativeOrAuthority,
    PathOrAuthority,
    Relative,
    RelativeSlash,
    SpecialAuthoritySlashes,
    SpecialAuthorityIgnoreSlashes,
    Authority,
    Host,
    Port,
    File,
    FileSlash,
    FileHost,
    PathStart,
    Path,
    OpaquePath,
    Query,
    Fragment,
}

impl Url {
    pub fn parse(input: &str) -> Result<Url, ()> {
        Self::parse_with_base(input, None)
    }

    pub fn join(&self, input: &str) -> Result<Url, ()> {
        Self::parse_with_base(input, Some(self))
    }

    fn is_special(&self) -> bool {
        is_special(&self.scheme)
    }

    fn shorten_path(&mut self) {
        if self.scheme == "file" && self.path.len() == 1 {
            let p: Vec<char> = self.path[0].chars().collect();
            if is_windows_drive_letter(&p, true) {
                return;
            }
        }
        self.path.pop();
    }

    fn parse_with_base(input: &str, base: Option<&Url>) -> Result<Url, ()> {
        let trimmed = input.trim_matches(|c: char| (c as u32) <= 0x20);
        let chars: Vec<char> = trimmed.chars().filter(|&c| c != '\t' && c != '\n' && c != '\r').collect();
        let mut url = Url {
            scheme: String::new(),
            username: String::new(),
            password: String::new(),
            host: None,
            port: None,
            path: Vec::new(),
            opaque_path: None,
            query: None,
            fragment: None,
        };
        let mut state = St::SchemeStart;
        let mut buffer = String::new();
        let mut at_sign_seen = false;
        let mut inside_brackets = false;
        let mut password_token_seen = false;
        let mut p: usize = 0;
        loop {
            let c = chars.get(p).copied();
            match state {
                St::SchemeStart => match c {
                    Some(ch) if ch.is_ascii_alphabetic() => {
                        buffer.push(ch.to_ascii_lowercase());
                        state = St::Scheme;
                    }
                    _ => {
                        state = St::NoScheme;
                        continue;
                    }
                },
                St::Scheme => match c {
                    Some(ch) if ch.is_ascii_alphanumeric() || ch == '+' || ch == '-' || ch == '.' => {
                        buffer.push(ch.to_ascii_lowercase());
                    }
                    Some(':') => {
                        url.scheme = std::mem::take(&mut buffer);
                        if url.scheme == "file" {
                            state = St::File;
                        } else if url.is_special() && base.map(|b| b.scheme == url.scheme).unwrap_or(false) {
                            state = St::SpecialRelativeOrAuthority;
                        } else if url.is_special() {
                            state = St::SpecialAuthoritySlashes;
                        } else if chars.get(p + 1) == Some(&'/') {
                            state = St::PathOrAuthority;
                            p += 1;
                        } else {
                            url.opaque_path = Some(String::new());
                            state = St::OpaquePath;
                        }
                    }
                    _ => {
                        buffer.clear();
                        state = St::NoScheme;
                        p = 0;
                        continue;
                    }
                },
                St::NoScheme => {
                    let b = match base {
                        None => return Err(()),
                        Some(b) => b,
                    };
                    if b.opaque_path.is_some() && c != Some('#') {
                        return Err(());
                    }
                    if b.opaque_path.is_some() && c == Some('#') {
                        url.scheme = b.scheme.clone();
                        url.opaque_path = b.opaque_path.clone();
                        url.query = b.query.clone();
                        url.fragment = Some(String::new());
                        state = St::Fragment;
                    } else if b.scheme != "file" {
                        state = St::Relative;
                        continue;
                    } else {
                        state = St::File;
                        continue;
                    }
                }
                St::SpecialRelativeOrAuthority => {
                    if c == Some('/') && chars.get(p + 1) == Some(&'/') {
                        state = St::SpecialAuthorityIgnoreSlashes;
                        p += 1;
                    } else {
                        state = St::Relative;
                        continue;
                    }
                }
                St::PathOrAuthority => {
                    if c == Some('/') {
                        state = St::Authority;
                    } else {
                        state = St::Path;
                        continue;
                    }
                }
                St::Relative => {
                    let b = base.unwrap();
                    url.scheme = b.scheme.clone();
                    if c == Some('/') {
                        state = St::RelativeSlash;
                    } else if url.is_special() && c == Some('\\') {
                        state = St::RelativeSlash;
                    } else {
                        url.username = b.username.clone();
                        url.password = b.password.clone();
                        url.host = b.host.clone();
                        url.port = b.port;
                        url.path = b.path.clone();
                        url.query = b.query.clone();
                        if c == Some('?') {
                            url.query = Some(String::new());
                            state = St::Query;
                        } else if c == Some('#') {
                            url.fragment = Some(String::new());
                            state = St::Fragment;
                        } else if c.is_some() {
                            url.query = None;
                            url.shorten_path();
                            state = St::Path;
                            continue;
                        }
                    }
                }
                St::RelativeSlash => {
                    if url.is_special() && (c == Some('/') || c == Some('\\')) {
                        state = St::SpecialAuthorityIgnoreSlashes;
                    } else if c == Some('/') {
                        state = St::Authority;
                    } else {
                        let b = base.unwrap();
                        url.username = b.username.clone();
                        url.password = b.password.clone();
                        url.host = b.host.clone();
                        url.port = b.port;
                        state = St::Path;
                        continue;
                    }
                }
                St::SpecialAuthoritySlashes => {
                    if c == Some('/') && chars.get(p + 1) == Some(&'/') {
                        state = St::SpecialAuthorityIgnoreSlashes;
                        p += 1;
                    } else {
                        state = St::SpecialAuthorityIgnoreSlashes;
                        continue;
                    }
                }
                St::SpecialAuthorityIgnoreSlashes => {
                    if c != Some('/') && c != Some('\\') {
                        state = St::Authority;
                        continue;
                    }
                }
                St::Authority => {
                    if c == Some('@') {
                        if at_sign_seen {
                            buffer.insert_str(0, "%40");
                        }
                        at_sign_seen = true;
                        for bc in buffer.chars() {
                            if bc == ':' && !password_token_seen {
                                password_token_seen = true;
                                continue;
                            }
                            if password_token_seen {
                                pct_encode(&mut url.password, bc, in_userinfo_set);
                            } else {
                                pct_encode(&mut url.username, bc, in_userinfo_set);
                            }
                        }
                        buffer.clear();
                    } else if c.is_none()
                        || c == Some('/')
                        || c == Some('?')
                        || c == Some('#')
                        || (url.is_special() && c == Some('\\'))
                    {
                        if at_sign_seen && buffer.is_empty() {
                            return Err(());
                        }
                        p -= buffer.chars().count();
                        buffer.clear();
                        state = St::Host;
                        continue;
                    } else {
                        buffer.push(c.unwrap());
                    }
                }
                St::Host => {
                    if c == Some(':') && !inside_brackets {
                        if buffer.is_empty() {
                            return Err(());
                        }
                        let h = parse_host(&buffer, !url.is_special()).ok_or(())?;
                        url.host = Some(h);
                        buffer.clear();
                        state = St::Port;
                    } else if c.is_none()
                        || c == Some('/')
                        || c == Some('?')
                        || c == Some('#')
                        || (url.is_special() && c == Some('\\'))
                    {
                        if url.is_special() && buffer.is_empty() {
                            return Err(());
                        }
                        let h = if buffer.is_empty() {
                            Host::Empty
                        } else {
                            parse_host(&buffer, !url.is_special()).ok_or(())?
                        };
                        url.host = Some(h);
                        buffer.clear();
                        state = St::PathStart;
                        continue;
                    } else {
                        let ch = c.unwrap();
                        if ch == '[' {
                            inside_brackets = true;
                        }
                        if ch == ']' {
                            inside_brackets = false;
                        }
                        buffer.push(ch);
                    }
                }
                St::Port => match c {
                    Some(ch) if ch.is_ascii_digit() => buffer.push(ch),
                    _ if c.is_none()
                        || c == Some('/')
                        || c == Some('?')
                        || c == Some('#')
                        || (url.is_special() && c == Some('\\')) =>
                    {
                        if !buffer.is_empty() {
                            let mut v: u32 = 0;
                            for d in buffer.chars() {
                                v = v * 10 + d.to_digit(10).unwrap();
                                if v > 65535 {
                                    return Err(());
                                }
                            }
                            let v = v as u16;
                            url.port = if default_port(&url.scheme) == Some(v) { None } else { Some(v) };
                            buffer.clear();
                        }
                        state = St::PathStart;
                        continue;
                    }
                    _ => return Err(()),
                },
                St::File => {
                    url.scheme = "file".to_string();
                    url.host = Some(Host::Empty);
                    if c == Some('/') || c == Some('\\') {
                        state = St::FileSlash;
                    } else if let Some(b) = base.filter(|b| b.scheme == "file") {
                        url.host = b.host.clone();
                        url.path = b.path.clone();
                        url.query = b.query.clone();
                        if c == Some('?') {
                            url.query = Some(String::new());
                            state = St::Query;
                        } else if c == Some('#') {
                            url.fragment = Some(String::new());
                            state = St::Fragment;
                        } else if c.is_some() {
                            url.query = None;
                            if !starts_with_windows_drive_letter(&chars[p..]) {
                                url.shorten_path();
                            } else {
                                url.path.clear();
                            }
                            state = St::Path;
                            continue;
                        }
                    } else {
                        state = St::Path;
                        continue;
                    }
                }
                St::FileSlash => {
                    if c == Some('/') || c == Some('\\') {
                        state = St::FileHost;
                    } else {
                        if let Some(b) = base.filter(|b| b.scheme == "file") {
                            url.host = b.host.clone();
                            if !starts_with_windows_drive_letter(&chars[p..]) && !b.path.is_empty() {
                                let first: Vec<char> = b.path[0].chars().collect();
                                if is_windows_drive_letter(&first, true) {
                                    url.path.push(b.path[0].clone());
                                }
                            }
                        }
                        state = St::Path;
                        continue;
                    }
                }
                St::FileHost => {
                    if c.is_none() || matches!(c, Some('/') | Some('\\') | Some('?') | Some('#')) {
                        let bchars: Vec<char> = buffer.chars().collect();
                        if is_windows_drive_letter(&bchars, false) {
                            state = St::Path;
                        } else if buffer.is_empty() {
                            url.host = Some(Host::Empty);
                            state = St::PathStart;
                        } else {
                            let mut h = parse_host(&buffer, false).ok_or(())?;
                            if h == Host::Domain("localhost".to_string()) {
                                h = Host::Empty;
                            }
                            url.host = Some(h);
                            buffer.clear();
                            state = St::PathStart;
                        }
                        continue;
                    } else {
                        buffer.push(c.unwrap());
                    }
                }
                St::PathStart => {
                    if url.is_special() {
                        state = St::Path;
                        if c != Some('/') && c != Some('\\') {
                            continue;
                        }
                    } else if c == Some('?') {
                        url.query = Some(String::new());
                        state = St::Query;
                    } else if c == Some('#') {
                        url.fragment = Some(String::new());
                        state = St::Fragment;
                    } else if c.is_some() {
                        state = St::Path;
                        if c != Some('/') {
                            continue;
                        }
                    }
                }
                St::Path => {
                    let end = c.is_none()
                        || c == Some('/')
                        || (url.is_special() && c == Some('\\'))
                        || c == Some('?')
                        || c == Some('#');
                    if end {
                        let slash = c == Some('/') || (url.is_special() && c == Some('\\'));
                        if is_double_dot(&buffer) {
                            url.shorten_path();
                            if !slash {
                                url.path.push(String::new());
                            }
                        } else if is_single_dot(&buffer) && !slash {
                            url.path.push(String::new());
                        } else if !is_single_dot(&buffer) {
                            let bchars: Vec<char> = buffer.chars().collect();
                            if url.scheme == "file" && url.path.is_empty() && is_windows_drive_letter(&bchars, false) {
                                buffer = format!("{}:", bchars[0]);
                            }
                            url.path.push(buffer.clone());
                        }
                        buffer.clear();
                        if c == Some('?') {
                            url.query = Some(String::new());
                            state = St::Query;
                        }
                        if c == Some('#') {
                            url.fragment = Some(String::new());
                            state = St::Fragment;
                        }
                    } else {
                        pct_encode(&mut buffer, c.unwrap(), in_path_set);
                    }
                }
                St::OpaquePath => {
                    if c == Some('?') {
                        url.query = Some(String::new());
                        state = St::Query;
                    } else if c == Some('#') {
                        url.fragment = Some(String::new());
                        state = St::Fragment;
                    } else if let Some(ch) = c {
                        let op = url.opaque_path.get_or_insert_with(String::new);
                        pct_encode(op, ch, in_c0_set);
                    }
                }
                St::Query => {
                    if c == Some('#') || c.is_none() {
                        let special = url.is_special();
                        let q = url.query.get_or_insert_with(String::new);
                        for bc in buffer.chars() {
                            pct_encode(q, bc, if special { in_special_query_set } else { in_query_set });
                        }
                        buffer.clear();
                        if c == Some('#') {
                            url.fragment = Some(String::new());
                            state = St::Fragment;
                        }
                    } else {
                        buffer.push(c.unwrap());
                    }
                }
                St::Fragment => {
                    if let Some(ch) = c {
                        let f = url.fragment.get_or_insert_with(String::new);
                        pct_encode(f, ch, in_fragment_set);
                    }
                }
            }
            if c.is_none() {
                break;
            }
            p += 1;
        }
        Ok(url)
    }

    pub fn serialize(&self) -> String {
        let mut s = String::new();
        s.push_str(&self.scheme);
        s.push(':');
        if let Some(h) = &self.host {
            s.push_str("//");
            if !self.username.is_empty() || !self.password.is_empty() {
                s.push_str(&self.username);
                if !self.password.is_empty() {
                    s.push(':');
                    s.push_str(&self.password);
                }
                s.push('@');
            }
            s.push_str(&host_to_string(h));
            if let Some(port) = self.port {
                s.push(':');
                s.push_str(&port.to_string());
            }
        }
        if let Some(op) = &self.opaque_path {
            s.push_str(op);
        } else {
            if self.host.is_none() && self.path.len() > 1 && self.path[0].is_empty() {
                s.push_str("/.");
            }
            for seg in &self.path {
                s.push('/');
                s.push_str(seg);
            }
        }
        if let Some(q) = &self.query {
            s.push('?');
            s.push_str(q);
        }
        if let Some(f) = &self.fragment {
            s.push('#');
            s.push_str(f);
        }
        s
    }
}

fn host_to_string(h: &Host) -> String {
    match h {
        Host::Domain(d) => d.clone(),
        Host::Opaque(o) => o.clone(),
        Host::Empty => String::new(),
        Host::Ipv4(v) => format!("{}.{}.{}.{}", v >> 24, (v >> 16) & 255, (v >> 8) & 255, v & 255),
        Host::Ipv6(a) => {
            // find longest run of zeros (length >= 2)
            let mut best: Option<(usize, usize)> = None;
            let mut i = 0;
            while i < 8 {
                if a[i] == 0 {
                    let start = i;
                    while i < 8 && a[i] == 0 {
                        i += 1;
                    }
                    let len = i - start;
                    if len >= 2 && best.map(|(_, l)| len > l).unwrap_or(true) {
                        best = Some((start, len));
                    }
                } else {
                    i += 1;
                }
            }
            let mut s = String::from("[");
            let mut ignore0 = false;
            let mut i = 0;
            while i < 8 {
                if let Some((st, len)) = best {
                    if i == st {
                        s.push_str(if i == 0 { "::" } else { ":" });
                        i += len;
                        ignore0 = true;
                        continue;
                    }
                }
                let _ = ignore0;
                s.push_str(&format!("{:x}", a[i]));
                if i != 7 {
                    s.push(':');
                }
                i += 1;
            }
            s.push(']');
            s
        }
    }
}
