                    url.host = Some(Host::Empty);
                    if c == Some('/') || c == Some('\\') {
                        state = St::FileSlash;
                    } else if let Some(b) = base.filter(|b| b.scheme == "file") {
                        url.host = b.host.clone();
                        url.path = b.path.clone();
                        url.query = b.query.clone();
                        if c == Some('?') {
                            url.query = Some(String::new());
                            state = St::Query;
                        } else if c == Some('#') {
                            url.fragment = Some(String::new());
                            state = St::Fragment;
                        } else if c.is_some() {
                            url.query = None;
                            if !starts_with_windows_drive_letter(&chars[p..]) {
                                url.shorten_path();
                            } else {
                                url.path.clear();
                            }
                            state = St::Path;
                            continue;
                        }
                    } else {
                        state = St::Path;
                        continue;
                    }
                }
                St::FileSlash => {
                    if c == Some('/') || c == Some('\\') {
                        state = St::FileHost;
                    } else {
                        if let Some(b) = base.filter(|b| b.scheme == "file") {
                            url.host = b.host.clone();
                            if !starts_with_windows_drive_letter(&chars[p..]) && !b.path.is_empty() {
                                let first: Vec<char> = b.path[0].chars().collect();
                                if is_windows_drive_letter(&first, true) {
                                    url.path.push(b.path[0].clone());
                                }
                            }
                        }
                        state = St::Path;
                        continue;
                    }
                }
                St::FileHost => {
                    if c.is_none() || matches!(c, Some('/') | Some('\\') | Some('?') | Some('#')) {
                        let bchars: Vec<char> = buffer.chars().collect();
                        if is_windows_drive_letter(&bchars, false) {
                            state = St::Path;
                        } else if buffer.is_empty() {
                            url.host = Some(Host::Empty);
                            state = St::PathStart;
                        } else {
                            let mut h = parse_host(&buffer, false).ok_or(())?;
                            if h == Host::Domain("localhost".to_string()) {
                                h = Host::Empty;
                            }
                            url.host = Some(h);
                            buffer.clear();
                            state = St::PathStart;
                        }
                        continue;
                    } else {
                        buffer.push(c.unwrap());
                    }
                }
                St::PathStart => {
                    if url.is_special() {
                        state = St::Path;
                        if c != Some('/') && c != Some('\\') {
                            continue;
                        }
                    } else if c == Some('?') {
                        url.query = Some(String::new());
                        state = St::Query;
                    } else if c == Some('#') {
                        url.fragment = Some(String::new());
                        state = St::Fragment;
                    } else if c.is_some() {
                        state = St::Path;
                        if c != Some('/') {
                            continue;
                        }
                    }
                }
                St::Path => {
                    let end = c.is_none()
                        || c == Some('/')
                        || (url.is_special() && c == Some('\\'))
                        || c == Some('?')
                        || c == Some('#');
                    if end {
                        let slash = c == Some('/') || (url.is_special() && c == Some('\\'));
                        if is_double_dot(&buffer) {
                            url.shorten_path();
                            if !slash {
                                url.path.push(String::new());
                            }
                        } else if is_single_dot(&buffer) && !slash {
                            url.path.push(String::new());
                        } else if !is_single_dot(&buffer) {
                            let bchars: Vec<char> = buffer.chars().collect();
                            if url.scheme == "file" && url.path.is_empty() && is_windows_drive_letter(&bchars, false) {
                                buffer = format!("{}:", bchars[0]);
                            }
                            url.path.push(buffer.clone());
                        }
                        buffer.clear();
                        if c == Some('?') {
                            url.query = Some(String::new());
                            state = St::Query;
                        }
                        if c == Some('#') {
                            url.fragment = Some(String::new());
                            state = St::Fragment;
                        }
                    } else {
                        pct_encode(&mut buffer, c.unwrap(), in_path_set);
                    }
                }
                St::OpaquePath => {
                    if c == Some('?') {
                        url.query = Some(String::new());
                        state = St::Query;
                    } else if c == Some('#') {
                        url.fragment = Some(String::new());
                        state = St::Fragment;
                    } else if let Some(ch) = c {
                        let op = url.opaque_path.get_or_insert_with(String::new);
                        pct_encode(op, ch, in_c0_set);
                    }
                }
                St::Query => {
                    if c == Some('#') || c.is_none() {
                        let special = url.is_special();
                        let q = url.query.get_or_insert_with(String::new);
                        for bc in buffer.chars() {
                            pct_encode(q, bc, if special { in_special_query_set } else { in_query_set });
                        }
                        buffer.clear();
                        if c == Some('#') {
                            url.fragment = Some(String::new());
                            state = St::Fragment;
                        }
                    } else {
                        buffer.push(c.unwrap());
                    }
                }
                St::Fragment => {
                    if let Some(ch) = c {
                        let f = url.fragment.get_or_insert_with(String::new);
                        pct_encode(f, ch, in_fragment_set);
                    }
                }
            }
            if c.is_none() {
                break;
            }
            p += 1;
        }
        Ok(url)
    }

    pub fn serialize(&self) -> String {
        let mut s = String::new();
        s.push_str(&self.scheme);
        s.push(':');
        if let Some(h) = &self.host {
            s.push_str("//");
            if !self.username.is_empty() || !self.password.is_empty() {
                s.push_str(&self.username);
                if !self.password.is_empty() {
                    s.push(':');
                    s.push_str(&self.password);
                }
                s.push('@');
            }
            s.push_str(&host_to_string(h));
            if let Some(port) = self.port {
                s.push(':');
                s.push_str(&port.to_string());
            }
        }
        if let Some(op) = &self.opaque_path {
            s.push_str(op);
        } else {
            if self.host.is_none() && self.path.len() > 1 && self.path[0].is_empty() {
                s.push_str("/.");
            }
            for seg in &self.path {
                s.push('/');
                s.push_str(seg);
            }
        }
        if let Some(q) = &self.query {
            s.push('?');
            s.push_str(q);
        }
        if let Some(f) = &self.fragment {
            s.push('#');
            s.push_str(f);
        }
        s
    }
}

fn host_to_string(h: &Host) -> String {
    match h {
        Host::Domain(d) => d.clone(),
        Host::Opaque(o) => o.clone(),
        Host::Empty => String::new(),
        Host::Ipv4(v) => format!("{}.{}.{}.{}", v >> 24, (v >> 16) & 255, (v >> 8) & 255, v & 255),
        Host::Ipv6(a) => {
            // find longest run of zeros (length >= 2)
            let mut best: Option<(usize, usize)> = None;
            let mut i = 0;
            while i < 8 {
                if a[i] == 0 {
                    let start = i;
                    while i < 8 && a[i] == 0 {
                        i += 1;
                    }
                    let len = i - start;
                    if len >= 2 && best.map(|(_, l)| len > l).unwrap_or(true) {
                        best = Some((start, len));
                    }
                } else {
                    i += 1;
                }
            }
            let mut s = String::from("[");
            let mut ignore0 = false;
            let mut i = 0;
            while i < 8 {
                if let Some((st, len)) = best {
                    if i == st {
                        s.push_str(if i == 0 { "::" } else { ":" });
                        i += len;
                        ignore0 = true;
                        continue;
                    }
                }
                let _ = ignore0;
                s.push_str(&format!("{:x}", a[i]));
                if i != 7 {
                    s.push(':');
                }
                i += 1;
            }
            s.push(']');
            s
        }
    }
}
