    while let Some(edge) = trav.next(&dom) {
        let node = match edge {
            Edge::Start(n) => n,
            Edge::End(_) => continue,
        };
        if !dom.is_element(node) || !selector.matches(&dom, node) {
            continue;
        }

        // Remove nodes: the first matching node (if any) is detached and the
        // current match is skipped.
        let mut skip = false;
        for rs in remove.iter().flatten() {
            let mut t = Traverse::new(node);
            let mut found = None;
            while let Some(e) = t.next(&dom) {
                if let Edge::Start(m) = e {
                    if dom.is_element(m) && rs.matches(&dom, m) {
                        found = Some(m);
                        break;
                    }
                }
            }
            if let Some(m) = found {
                dom.detach(m);
                skip = true;
                break;
            }
        }
        if skip {
            continue;
        }

        if let Some(b) = &base {
            let rewrite = match dom.element(node) {
                Some(e) => matches!(e.local.as_str(), "a" | "link" | "area"),
                None => false,
            };
            if rewrite {
                let href = dom.element(node).unwrap().get_attr("href").map(|s| s.to_string());
                if let Some(h) = href {
                    let new = match b.join(&h) {
                        Ok(u) => u.serialize(),
                        Err(()) => b.serialize(),
                    };
                    dom.element_mut(node).unwrap().set_attr("href", new);
                }
            }
        }

        if let Some(attr) = &cfg.attribute {
            let v = dom.element(node).unwrap().get_attr(attr).map(|s| s.to_string());
            if let Some(v) = v {
                output.write_all(v.as_bytes())?;
                output.write_all(b"\n")?;
            }
            continue;
        }

        if cfg.text {
            let mut buf = String::new();
            let mut t = Traverse::new(node);
            while let Some(e) = t.next(&dom) {
                if let Edge::Start(m) = e {
                    if let Some(txt) = dom.text(m) {
                        if cfg.ignore_whitespace {
                            if txt.trim().is_empty() {
                                continue;
                            }
                            buf.push_str(txt);
                            buf.push('\n');
                        } else {
                            buf.push_str(txt);
                        }
                    }
                }
            }
            buf.push('\n');
            output.write_all(buf.as_bytes())?;
            continue;
        }

        let mut s = String::new();
        if cfg.pretty {
            serialize::pretty(&dom, node, &mut s);
        } else {
            serialize::serialize(&dom, node, &mut s);
        }
        s.push('\n');
        output.write_all(s.as_bytes())?;
    }
    output.flush()?;
    Ok(())
}
