fn process_match(
    dom: &mut Dom,
    node: NodeId,
    cfg: &cli::Config,
    base: &Option<url::Url>,
    remove: &[Option<css::SelectorList>],
    output: &mut Box<dyn Write>,
) -> std::io::Result<()> {
    // Remove nodes: the first matching node (if any) is detached and the
    // current match is skipped.
    for rs in remove.iter().flatten() {
        let mut t = RcTraverse::new(dom, node);
        let mut found = None;
        while let Some(e) = t.next(dom) {
            if let Edge::Start(m) = e {
                if dom.is_element(m) && rs.matches(dom, m) {
                    found = Some(m);
                    break;
                }
            }
            dom.dec(e.node());
        }
