        let mut buf = String::new();
        let mut t = Traverse::new(node);
        while let Some(e) = t.next(dom) {
            if let Edge::Start(m) = e {
                if let Some(txt) = dom.text(m) {
                    if cfg.ignore_whitespace {
                        if txt.trim().is_empty() {
                            continue;
                        }
                        buf.push_str(txt);
                        buf.push('\\n');
                    } else {
                        buf.push_str(txt);
                    }
                }
            }
