        '\u{0080}'..='\u{009F}' | '\u{FFFD}' | '\u{FFFE}' | '\u{FFFF}' => return false,
        '\u{00DF}' => out.push(c),
        _ => {
            for l in c.to_lowercase() {
                out.push(l);
            }
        }
    }
