fn label_char_valid(c: char) -> bool {
    !(c.is_uppercase()
        || (c as u32) < 0x20
        || ('\u{007F}'..='\u{009F}').contains(&c)
        || matches!(c, '\u{FFFD}' | '\u{FFFE}' | '\u{FFFF}' | '\u{00AD}' | '\u{200B}' | '\u{FEFF}'))
}

fn domain_to_ascii(domain: &str) -> Option<String> {
    let mut mapped: Vec<char> = Vec::new();
    for c in domain.chars() {
        if !uts46_map(c, &mut mapped) {
            return None;
        }
    }
    let mapped: String = mapped.into_iter().collect();
    let mut out = Vec::new();
    for label in mapped.split('.') {
        let chars: Vec<char> = if let Some(rest) = label.strip_prefix("xn--") {
            let dec = punycode_decode(rest)?;
            if dec.is_empty() || !dec.iter().all(|&c| label_char_valid(c)) {
                return None;
            }
            dec
        } else {
            label.chars().collect()
        };
        if chars.iter().all(|c| c.is_ascii()) {
            out.push(chars.into_iter().collect::<String>());
        } else {
            out.push(format!("xn--{}", punycode_encode(&chars)?));
        }
    }
    Some(out.join("."))
}

